        minipack = 0,
    },
    [2081377] = {
        id = 2081377,
        text = "Es heißt, dass Feinde am Drachenboot-Festival herauskommen würden und Klebreis sie vertreiben kann. Außerdem ist es ein notwendiges Material zur Herstellung von Zongzi.",
        minipack = 0,
    },
    [2081378] = {
        id = 2081378,
        text = "Der saturierte Mais schmeckt süß und erfrischend. Dadurch schmeckt Zongzi besser.",
        minipack = 0,
    },
    [2081379] = {
        id = 2081379,
        text = "Die kleine Erdnuss steckt voller Energie. Es lässt Zongzi noch besser riechen.",
        minipack = 0,
    },
    [2081380] = {
        id = 2081380,
        text = "Beim Drachenboot-Festival ist Fleisch ein Muss! 40% Fett und 60% mageres Fleisch ist das Geheimnis des magischen Zongzi.",
        minipack = 0,
    },
    [2081381] = {
        id = 2081381,
        text = "Eigelb verleiht Zongzi nicht nur einen besseren Geschmack, sondern auch ein attraktives goldenes Aussehen.",
        minipack = 0,
    },
    [2081382] = {
        id = 2081382,
        text = "Rote Bohnenpaste lässt Zongzi fein und geschmeidig schmecken, mit anhaltendem Aroma.",
        minipack = 0,
    },
    [2081383] = {
