    [10951231] = {
        id = 10951231,
        text = "Wenn Kurokos passive Fähigkeiten Schaden verursachen, besteht eine 30% Chance, eine weitere explosive Bombe zu teleportieren, die Physischen SCH in Höhe von 80% des ANG des Charakters verursacht. Auch effektiv, wenn der Charakter nicht im Kampf ist.",
