    },
    [13310531] = {
        id = 13310531,
        text = "Liebe Paktpartner, \n In diesem Frühsommer werden wir ein großes Update mit vielen großartigen neuen Funktionen auf den Markt bringen!\n Wir haben viele neue Spielmodi und Inhalte vorbereitet, darunter Sharam-Tor, Kampf um Territorium und Runenstein-Herausforderung. Wir wünschen euch aufrichtig viel Spaß mit dem Update. \n Wir schätzen eure Unterstützung und Toleranz sehr!\n Dating hört nie auf! Wir lieben euch alle!\n - Designer Sima",
        minipack = 0,
    },
    [13310539] = {
        id = 13310539,
        text = "Liebe Paktpartner, \n Bald wird ein weiteres charismatisches Idol verfügbar sein! Außerdem ist die Stimme eurer Waifu Mayuri jetzt verfügbar! Was würde Mayuri sagen?\n Aufgrund des Terminkalenders der Synchronsprecherin wurde die neue Stimme nicht wie geplant hinzugefügt. Dennoch haben wir es am Ende geschafft!\n Hot Games wird dieses Spiel weiter verbessern und euch bessere Inhalte bieten. Neue Inhalte kommen vielleicht spät, aber sie kommen garantiert. \n Hot Games",
        minipack = 0,
    },
    [13310547] = {
        id = 13310547,
        text = "Voller Erinnerungen.",
        minipack = 0,
    },
    [13310555] = {
        id = 13310555,
        text = "Komm zu mir! Lobe mich, wie du willst! Hey! Was genau... ist diese seltsame Bitte?!",
        minipack = 0,
    },
    [13310563] = {
        id = 13310563,
        text = "Während ich den Weihnachtsbaum mit Kotori und Tohka schmückte, erhielt ich ein unerwartetes Geschenk.",
        minipack = 0,
    },
    [252021] = {
