    [14230005] = {
        id = 14230005,
        text = "Manchmal wünscht man sich vielleicht, eine andere Person zu sein. Aber tatsächlich machen Fleiß und Zeit immer einen Unterschied.",
        minipack = 0,
    },
    [14230013] = {
        id = 14230013,
        text = "Die Magie der Zeit liegt nicht in den Konstanten, sondern darin, dass man sich auch nach 1 Jahr noch an die Leidenschaft des Augenblicks erinnert. Herzlichen Glückwunsch zum ersten Jahrestag, Darling!",
        minipack = 0,
    },
    [63014] = {
        id = 63014,
        text = "Das Spiel hat keinen Mangel an verschiedenen Events, wie z.B. der Quest-Event, bei dem du groß gewinnen kannst, nachdem du die Questbedingungen erfüllt hast, und der Shop-Event, bei dem du gesammelte Gegenstände gegen Eventgegenstände eintauschen kannst. Achte genau auf die Bekanntmachungen im Spiel und andere Hinweise. \n\nBei der Berechnung des Gesamtaufladung-Events wird aufgerundet. z.B. wird ein Aufladen von $0,99 als $1 gezählt. \n\nJe mehr Leute während des Kostüm-Vorverkauf Events am Vorverkauf teilnehmen, desto höher ist der Rabatt.\nWenn die kumulative Teilnehmerzahl des Vorverkaufs 500, 1000, 1500, 2000 erreicht, kann das Kostüm mit 5%, 10%, 15% bzw. 20% Rabatt gekauft werden, wenn es offiziell verkauft wird. \nDer Restbetrag ist der rabattierte Preis abzüglich der Vorauszahlung. Spielern, die vorbestellt, aber den Restbetrag nicht bezahlt haben, werden nach dem Event 300 Diamanten per Mail im Spiel zurückgeschickt.",
        minipack = 0,
    },
