    [13194] = {
        id = 13194,
        text = "Gedenkabzeichen der Kollaborationskämpfe. Das Schwert ist ein Symbol der Freundschaft. Dient zum Tausch von Gegenständen im Neptunia Kollaborations-Shop, die aus dem Kollaborationsevent und dem Kollaborations-Kartenpool mit der Neptunia-Reihe stammen.",
        minipack = 0,
    },
    [63015] = {
        id = 63015,
        text = "Vorteile ist wie permanente Events. \n Melde dich täglich an, um Belohnungen abzuholen. Diese Belohnungen werden sich jeden Monat ändern. Liebes-Bento stellt zweimal täglich die Ausdauer wieder her. Vergiss nicht, dein Bento abzuholen~",
