    [63017] = {
        id = 63017,
        text = "Es gibt 3 reguläre Questtypen: Haupt, Tages und Erfolge und 1 Event-Quest - Herz der Prinzessin. Schließe sie ab und du wirst großartige Belohnungen erhalten. \nHaupt-Quests sind mit der Geschichte verbunden, normalerweise musst du eine Instanz herausfordern. \nTägliche Quests sind mit verschiedenen Modi des Spiels verbunden. Schließe sie ab, um Aktivitätspunkte und Belohnungen zu erhalten. Tägliche Quests werden täglich aktualisiert. Nicht abgeholte Belohnungen werden dir nach der Aktualisierung per Mail zugeschickt. \n Erfolge bieten anständige Herausforderungen im Spiel. Je schwieriger die Herausforderung, desto besser die Belohnung. \nIm Event Herz der Prinzessin erhältst du Event-EP durch tägliche Quests und tägliche Quests. Das Eventlevel steigt, sobald du genug EP hast. \nDu kannst Eventbelohnungen abholen, sobald dein Eventlevel hoch genug ist.",
        minipack = 0,
    },
