        text = "Herz ausdrücken",
        minipack = 0,
    },
    [63021] = {
        id = 63021,
        text = "Man muss sich vor einem Kampf gut vorbereiten. Setze je nach den Bedingungen jeder Stufe unterschiedliche Charaktere ein. Beachte, dass du in der Welt von Date A Live keine doppelten Charaktere einsetzen kannst (außer Unterstützern). Beispiel: Wenn du Tohka Yatogami eingesetzt hast, kannst du Shekinah Tohka und Invertierte Tohka nicht einsetzen.",
        minipack = 0,
    },
    [910002] = {
        id = 910002,
        text = "\"Wir sind nicht gleich, stimmt's?\" Tohka richtete ihr Schwert auf mich. Was soll ich tun?",
        minipack = 0,
    },
    [910003] = {
        id = 910003,
        text = "Begleiten",
        minipack = 0,
    },
    [910004] = {
        id = 910004,
        text = "Tohkas einsamer Gesichtsausdruck gab mir ein schlechtes Gefühl. Richtig! Es wird das Problem lösen, wenn jemand (?) hier ist, um Tohka zu begleiten, nicht wahr?",
        minipack = 0,
    },
    [910005] = {
        id = 910005,
        text = "Fang deinen Magen!",
        minipack = 0,
