        minipack = 0,
    },
    [63022] = {
        id = 63022,
        text = "Im Gegensatz zur normalen Instanz wird die Tägliche Instanz nicht Stufe für Stufe freigeschaltet. Stattdessen musst du ein bestimmtes Level erreichen, um sie herauszufordern. Du hast jeden Tag begrenzte kostenlose Versuche, die Tägliche Instanz herauszufordern. Aber du kannst Diamanten ausgeben, um mehr zu kaufen.",
        minipack = 0,
    },
    [910018] = {
