    [63027] = {
        id = 63027,
        text = "Arbeiten ist eine großartige Möglichkeit, Belohnungen zu verdienen!\n\nEs braucht Zeit, um deine Arbeit abzuschließen und Belohnungen zu erhalten. Verschiedene Shops gewähren unterschiedliche Belohnungen. Arbeiten gewährt Arbeits-EP für diesen Job, erhalte genug EP, um das Arbeitslevel zu erhöhen, was zu besseren Bezahlungen führt~",
        minipack = 0,
    },
    [910098] = {
        id = 910098,
        text = "Märchen sind nicht wahr. Aber sie bewegen die Herzen aller.",
        minipack = 0,
    },
    [910099] = {
        id = 910099,
        text = "Es scheint, dass im Schrein ein großes Fest stattfindet. Wird es einen zeremoniellen Tanz geben...",
        minipack = 0,
    },
    [910100] = {
        id = 910100,
        text = "Hey, das ist unglaublich! Die Essensstraße bietet kostenlose Festmahle!",
        minipack = 0,
    },
    [910101] = {
        id = 910101,
        text = "Wenn die Kabine den oberen Punkt des Riesenrads erreicht, wird dein Wunsch in Erfüllung gehen.",
