    [910106] = {
        id = 910106,
        text = "Hände schütteln",
        minipack = 0,
    },
    [13316027] = {
        id = 13316027,
        text = "A maid hired by the villa, cute and adorable, but often screws things up. Supposedly she is a super fan of pop idol Miku Izayoi in private.",
        minipack = 0,
    },
    [910107] = {
        id = 910107,
        text = "Tödlicher Scharfschütze",
        minipack = 0,
    },
    [13316043] = {
        id = 13316043,
        text = "A junior high school girl whose composure makes her an excellent assistant to the detective.",
        minipack = 0,
    },
    [910108] = {
        id = 910108,
        text = "Gewöhnliche Wahrheit",
        minipack = 0,
    },
    [13316059] = {
        id = 13316059,
        text = "The murderer is a ghost... please believe me...",
        minipack = 0,
    },
    [910109] = {
        id = 910109,
        text = "Geschenk des neuen Freundes",
        minipack = 0,
    },
    [910110] = {
        id = 910110,
        text = "Kampf-Drill",
        minipack = 0,
    },
    [910111] = {
        id = 910111,
        text = "Um den Kampf zwischen Tohka und Origami zu beenden, muss ich mich vielleicht verletzen.",
        minipack = 0,
    },
    [13316107] = {
        id = 13316107,
        text = "Day.7",
        minipack = 0,
    },
    [910112] = {
        id = 910112,
        text = "Ich wurde angeschossen. Aber ich war trotzdem erleichtert zu sehen, dass Tohka und Origami die Dinge wieder in Ordnung bringen konnten.",
        minipack = 0,
    },
    [910113] = {
        id = 910113,
        text = "Tohka und Origami stritten um die Hasen-Haarnadel. Offenbar waren sie doch keine gewöhnlichen Mädchen.",
        minipack = 0,
    },
    [63028] = {
        id = 63028,
        text = "Willst du deinen geliebten Geist in der süßesten Kleidung auf der Startseite sehen?\n\n1. Auf der Lieblings-Mädchen Seite kannst du Geister Kleidung anziehen und das beste Mädchen auswählen, das auf deiner Startseite angezeigt wird. \n\n2. Wähle in der Lieblings-Mädchen Avatar-Liste auf der linken Seite Avatare von freigeschalteten Geistern aus und tippe rechts auf \"Wechseln\", um das Lieblings-Mädchen zu ändern. \n\n3. Du kannst auf die Tabs \"Ändern\", \"Info\" und \"Pose\" tippen, um eine Vorschau der Effekte zu sehen, bevor du die Änderung vornimmst. \n\n4. \"Ändern\": Ziehe Kostümkarten hierher, um zu prüfen, wie ein Geist in allen Kostümen aussieht. \n\n5. \"Info\": Hier findest du die Basis-Infos und die Hintergrundgeschichte jedes Geistes, vielleicht sogar ein paar private Dinge!\n\n6. \"Pose\": Du kannst überprüfen, wie die Geister reagieren, wenn du sie berührst. Wenn die Gunst nicht hoch genug ist, kannst du nur ein paar Linien sehen~\n\n7. Außerdem können alle \"gesperrten\" Inhalte auf der Seite angezeigt werden, was dir eine \"Orientierungshilfe im Voraus\" gibt.\n-------------------------------------------\n\nDiashow ist live!\n\nJetzt kannst du mehrere Geister in verschiedenen Kostümen (nur Fortgeschrittene) als Lieblings-Mädchen einstellen. Wenn Diashow eingeschaltet ist, wird das Lieblings-Mädchen in einem bestimmten Intervall auf der Startseite angezeigt.",
        minipack = 0,
    },
    [910114] = {
        id = 910114,
        text = "Die Sonderbehandlung von Tohka hat mir fast das Blut in den Adern gefrieren lassen. Ich denke, es ist an der Zeit, auch Yoshino zu erziehen.",
        minipack = 0,
    },
    [910115] = {
        id = 910115,
        text = "Ich glaube, dass Origami nicht absichtlich Fehler gemacht hat. Deshalb hoffte ich aufrichtig, dass Kusakabe senpai sie verschonen könnte.",
        minipack = 0,
    },
    [910116] = {
        id = 910116,
        text = "In der engen Gasse haben wir keine andere Wahl, als Origami zu konfrontieren. Der Kampf könnte jeden Moment ausbrechen.",
        minipack = 0,
    },
    [910117] = {
        id = 910117,
        text = "Als ich dachte, wir hätten Origami verloren, sah ich den roten Punkt eines Scharfschützen auf Tohkas Brust.",
        minipack = 0,
    },
    [13316203] = {
        id = 13316203,
        text = "Lyrics of the mourning song",
        minipack = 0,
    },
    [910118] = {
        id = 910118,
        text = "Tohka wurde an den Rand gedrängt. Ich hoffe, die Hasen-Haarnadel könnte ihr helfen.",
        minipack = 0,
    },
    [13316219] = {
        id = 13316219,
        text = "Daughter of the Amamiya Family",
        minipack = 0,
    },
    [910119] = {
        id = 910119,
        text = "Als ich aufwachte, hing ein Duft um meine Nase, und Tohkas Gesicht war so nah.",
        minipack = 0,
    },
    [13316235] = {
        id = 13316235,
        text = "[Analyze] Yuzuru's detailed statement",
        minipack = 0,
    },
    [910120] = {
        id = 910120,
        text = "Es ist für Tohka fast unmöglich, dem gut versteckten Scharfschützen auszuweichen. Würde sie getötet werden?",
        minipack = 0,
    },
    [13316251] = {
