    [63051] = {
        id = 63051,
        text = "Es gibt 2 Arten von Trainingskarten: Monatskarte und Wochenkarte. Mit dem Kauf wirst du sofort zum Trainer. \nDu kannst Tohka KI auf verschiedene Weisen verbessern: Behebe Probleme im Bug-Bildschirm, lehne falsche Antworten ab und nimm am Training Labor teil. Aktive Benutzer werden in der Geist KI-Rangliste aufgeführt und gewinnen einen exklusiven Avatar-Rahmen und einen exklusiven Titel. \nTrainingskarten verfallen 1 Woche/Monat nach dem Kauf und du kannst dann weiter trainieren oder die Trainingsrangliste und Trainerinfos aktualisieren, bevor du sie erneuerst. \nDu kannst Karten erneuern, um dein Training fortzusetzen.",
        minipack = 0,
    },
    [13322035] = {
        id = 13322035,
        text = "1. There are many ancient civilizations in this world. Dispatch airships to explore them, and complete civilization events to unlock more continents.",
        minipack = 0,
    },
    [13322043] = {
        id = 13322043,
        text = "9. Enter \"Civilization Module\" to view the layout of the current civilization and exploration info for each land.",
        minipack = 0,
    },
    [13322051] = {
        id = 13322051,
        text = "4. Each land will display the number of events already discovered. Players can enter a land to complete its event, or switch to a land to explore.",
        minipack = 0,
    },
