    [2200110] = {
        id = 2200110,
        text = "Schwingt Sandalphon, um angrenzende Feinde anzugreifen und macht 3 gerade Schläge. \nSchlag 1: Verursacht 1 Mal Physischen SCH in Höhe von 60% ANG; \nSchlag 2: Verursacht 1 Mal Physischen SCH in Höhe von 70% ANG; \nSchlag 3: Verursacht 1 Mal Physischen SCH in Höhe von 70% ANG.",
        minipack = 0,
    },
    [13322107] = {
        id = 13322107,
        text = "In Norse mythology, this evil black dragon lurks at Tree of World's root and gnaws at it constantly. Known as the darkest Dragon King, it has the evil power to subvert Midgard and Asgard. Airship \"Nidhogg\" has the same destructive power as the Black Dragon King and is hold in awe by people of the world",
        minipack = 0,
    },
    [2200120] = {
        id = 2200120,
        text = "Löst Wellen von Schwertstrahlen mit Sandalphon aus, um Feinde in der Front anzugreifen. \nVerursacht bei 3 Angriffen Physischen SCH in Höhe von 180% ANG.",
        minipack = 0,
    },
    [30502] = {
        id = 30502,
        text = "Spitzname: Efreet, ihr Charakter ändert sich je nach der Farbe ihrer Schleifen. Normalerweise ist sie die fähige und gerissene Kommandantin.",
        minipack = 0,
    },
    [2200130] = {
        id = 2200130,
        text = "Beschwört Paverschlev, um 4 Wellen von Schwertstrahlen nach vorne auszulösen. \nVerursacht bei 4 Angriffen Physischen SCH in Höhe von 750% ANG.",
        minipack = 0,
    },
    [244011] = {
