    [61004] = {
        id = 61004,
        text = "Sephira-Tipps",
        minipack = 0,
    },
    [63052] = {
        id = 63052,
        text = "Du kannst Tohka KI auf verschiedene Weisen verbessern: Behebe Probleme im Bug-Bildschirm, lehne falsche Antworten ab und nimm am Training Labor teil. \nBug-Bildschirm: Zeichnet alle abgelehnten Antworten von Tohka KI und die Fragen auf. Du kannst an der Simulation teilnehmen, um Tohka KI zu trainieren. Sobald deine Einreichung verifiziert ist, wird die Frage aus dem Bug-Bildschirm gelöscht, und deine verifizierte Antwort wird zu einer \"möglichen\" neuen Antwort auf die Frage. \nKI-Antworten ablehnen. Tippe auf \"Ablehnen\", wenn du mit Tohka KI chattest, um schlechte Antworten abzuwählen, dann kannst du eine andere Antwort geben oder die Frage ändern. \n Trainings-Labor: Reiche Fragen ein, mit denen Tohka KI trainieren kann. Schreib eine Antwort auf, mit der sie tatsächlich antworten wird, setze eine Auslösebedingung und reiche deine Arbeit ein. \nVerifizierungsliste: Zeichnet den Status der Trainingsinhalte auf.",
        minipack = 0,
    },
    [2200160] = {
        id = 2200160,
        text = "Wenn Tohka das Schlachtfeld betritt, folgt ihr der Thron, um angrenzende Feinde anzugreifen. \nVerursacht bei 1 Mal Physischen SCH in Höhe von 300% ANG.",
        minipack = 0,
