    [63055] = {
        id = 63055,
        text = "Mit dem Sephira-Filter kannst du das gewünschte Sephiroth schnell finden. Wenn du die Filteroption speicherst, werden nur qualifizierte Sephiroth aufgelistet. Sephira-Filter wird zurückgesetzt, wenn du offline gehst.",
