    [2200350] = {
        id = 2200350,
        text = "Sendet Eiszapfen aus, um Feinde in der Nähe anzugreifen. \nVerursacht 4 Mal Frost-SCH in Höhe von 20% ANG. Hat bei Treffer eine 60% Chance, Zittern zuzufügen. \n[Zittern reduziert die Bewegungsgeschwindigkeit für 6 Sek. um -10%; Wenn sich Zittern auf 5 Schichten stapelt, friert ein Ziel für 3 Sek. ein. ]",
        minipack = 0,
