    [2200370] = {
        id = 2200370,
        text = "Yoshinon erschafft ein Frostreich, das an Feinden im Inneren alle 0,3 Sek. SCH in Höhe von 30% ANG verursacht. Das Reich dauert 3 Sek. \nVerlangsamt Feinde, die von Frostreich beschädigt werden, um 20%.",
        minipack = 0,
