    [244026] = {
        id = 244026,
        text = "[Pigtailed Follower] left too much water on the floor after mopping, causing a customer to slip. Revenue -1,000",
        minipack = 0,
    },
    [2200380] = {
        id = 2200380,
        text = "Beschwört einen Tornado, der vorwärts fegt, dauert 1 Sek. \nVerursacht alle 0,2 Sek. Frost-SCH in Höhe von 70% ANG. Tornado hat eine 20% Chance, bei einem Treffer Zittern zu verursachen. \n[Zittern reduziert die Bewegungsgeschwindigkeit für 6 Sek um -10%; Wenn Zittern sich auf 5 Schichten stapelt, friert ein Ziel für 3 Sek. ein. ]",
        minipack = 0,
    },
