    [63056] = {
        id = 63056,
        text = "1. In Sephira-Voreinstellung kannst du aktuelle Sephiroth-Zuweisungen als voreingestellte Pläne speichern. \n 2. Du kannst diese voreingestellten Pläne auf jeden Geist anwenden. \n 3. Du kannst bis zu 20 Pläne speichern.",
        minipack = 0,
    },
    [2200420] = {
        id = 2200420,
        text = "Teleportiert sich in die Nähe eines Ziels und schießt dann mehrmals auf das Ziel. \nVerursacht 5 Mal Dunkel-SCH in Höhe von 108% ANG",
        minipack = 0,
    },
    [244029] = {
        id = 244029,
        text = "[Pigtailed Follower] invented a new drink called \"Mango Shaved Ice.\", which was a hit among young girls.",
        minipack = 0,
