    [244044] = {
        id = 244044,
        text = "[Stern and Cute] got into a fight with \"Sweet Commander\" as usual and is in a bad mood.",
        minipack = 0,
    },
    [63060] = {
        id = 63060,
        text = "1. Schließe den Zeitstrahl-Hinweis ab und du erhältst einen Zeit-Katalysator. Gib Katalysator*1 aus, um 1 Zeitgeheimnis zu enthüllen. Enthülltes Zeitgeheimnis kann nicht rückgängig gemacht werden. \n\n2. Wenn es 2 identische Zeitgeheimnisse gibt, erhältst du die geheime Belohnung und Zeitgeheimnisfragmente. \n\n3. Zeitgeheimnisfragmente können im Event-Shop gegen andere Gegenstände getauscht werden. \n\n4. Wenn alle Zeitgeheimnisse enthüllt sind, werden sie zurückgesetzt und eine neue Runde beginnt.",
        minipack = 0,
    },
