    [10951008] = {
        id = 10951008,
        text = "Eine Kampfstrategie, die Kuroko entwickelt hat, um den fehlenden AoE-Schaden ihrer Teleport-Fähigkeit auszugleichen. Sie durchtrennt alle tragenden Säulen eines Gebäudes, um es zu Fall zu bringen und verheerenden Schaden zu verursachen. Verursacht insgesamt 3000% Physischen SCH.",
