    [1500001] = {
        id = 1500001,
        text = "Ankündigung",
        minipack = 0,
    },
    [1500002] = {
        id = 1500002,
        text = "Liebe Spieler, \n\nTohka Yatogami: [Hallo zusammen, endlich haben wir uns kennengelernt!]\nKurumi Tokisaki: [Ara ara~ Guten Tag! Endlich haben wir uns getroffen. Danke für eure große Vorfreude, es ist toll, euch alle kennenzulernen.] \nOrigami Tobiichi: [Nach Erhalt der Lizenz von Kadokawa Shoten. Das Entwicklerteam hat hart daran gearbeitet, den Fans ein gut gemachtes Spiel zu bieten, das unsere DAL-Fans zufrieden stellen wird.] \nTohka Yatogami: [Umu~ Dies ist der erste öffentliche Betatest für alle Spieler. Es gibt noch eine Menge Probleme zu beseitigen. Entschuldigung für die Unannehmlichkeiten~ (Weinen in der Toilette T-T). In den wertvollen Tests haben wir viele Vorschläge und Feedbacks erhalten. Sie sind alle gut gelesen und sortiert. Außerdem... haben wir Pläne gemacht, das Spiel anzupassen. Die Änderungen werden zu unserem nächsten Date umgesetzt.] \nKotori Itsuka: [Wir verstehen, dass viele Feedback bezüglich der BGM, Geister-Bilder, Kampf und Spielfunktionen geschickt haben. Ratatoskr arbeitet hart daran, diese Aspekte zu verbessern. Bitte seid unbesorgt.] \nTohka Yatogami: [Sie wird von der Original Synchronsprecherin gesprochen!]\nOrigami Tobiichi: [Sie wird von der Original Synchronsprecherin gesprochen!]\nKotori Itsuka: [Sie wird von der Original Synchronsprecherin gesprochen!]\nKurumi Tokisaki: [Wenn ihr irgendwelche Fragen oder Wünsche habt, dann schließt euch bitte unserer Gruppe für diesen Test an: 542524583. Wir brauchen eure Hilfe, um das Spiel und unser Team besser zu machen.] \nOrigami Tobiichi: [Danke nochmals für eure Unterstützung. Ihr seid unsere größte Motivation, um voranzukommen.] \nTohka Yatogami: [Jetzt lasst unser Date (Kampf) beginnen!]\n\nP.S.: Bei diesem Test werden Tonnen von Vorteilen gewährt. Achtet darauf, euch jeden Tag anzumelden~\n\nWenn ihr auf Probleme stoßt, wendet euch an den Kundendienst QQ: 4000585151",
        minipack = 0,
    },
    [1500003] = {
        id = 1500003,
        text = "Danke, dass du am geschlossenen Betatest von Date A live teilgenommen hast (ähmmm... obwohl es viele Bugs gibt, an denen wir arbeiten müssen). \nVergiss beim Spielen nicht, diese Umfrage auszufüllen! Alles, was du sagst, beklagst oder ablehnst, wird an das HQ geschickt! Wir schätzen deine Meinung und werden jede Antwort sorgfältig lesen.",
        minipack = 0,
    },
