        minipack = 0,
    },
    [1701177] = {
        id = 1701177,
        text = "*Seufz*... Du wirst verwöhnt. Was werde ich mit dir machen?",
        minipack = 0,
    },
    [1701178] = {
        id = 1701178,
        text = "... Lass dich nicht stören. Geh auf Dates mit anderen Geistern",
        minipack = 0,
    },
    [1701179] = {
        id = 1701179,
        text = "Warum... warum muss ich bleiben? Ich habe meine Mission beendet.",
        minipack = 0,
    },
    [1701180] = {
        id = 1701180,
        text = "...! Willst du mich umarmen?... Warte, was soll ich tun?",
        minipack = 0,
    },
    [1701181] = {
        id = 1701181,
        text = "Haha... Es hat sich herausgestellt, dass deine Hände warm sind.",
        minipack = 0,
    },
    [1701182] = {
        id = 1701182,
        text = "Ähm... bleib am Leben. Ich kann- es fühlen.",
        minipack = 0,
    },
    [1701183] = {
        id = 1701183,
        text = "Wirklich? Ich... kann hier bleiben? Meinst du das ernst?",
        minipack = 0,
    },
    [1701184] = {
        id = 1701184,
        text = "Ich... Ich bin- nicht länger eine Existenz, die geboren wurde, um zu verschwinden...",
        minipack = 0,
    },
    [1701185] = {
        id = 1701185,
        text = "Ich liebe dich. Ich will nur mit dir zusammen sein... für immer.",
        minipack = 0,
    },
