    },
    [1701196] = {
        id = 1701196,
        text = "Nun... das Weihnachtsspezial ist ganz nett.",
        minipack = 0,
    },
    [1701197] = {
        id = 1701197,
        text = "Was machst du da?... Es kitzelt...",
        minipack = 0,
    },
    [1701198] = {
        id = 1701198,
        text = "Oh? Das ist dein Weihnachtswunsch?",
        minipack = 0,
    },
    [1701199] = {
        id = 1701199,
        text = "Warte... Ich weiß, es ist Weihnachten... aber ich bin nicht bereit dafür...",
        minipack = 0,
    },
    [1701200] = {
        id = 1701200,
        text = "Ara, bist du an meiner Weihnachtsmütze interessiert?",
        minipack = 0,
    },
    [1701201] = {
        id = 1701201,
        text = "Dies ist ein Weihnachtskostüm. Gefällt es dir?",
        minipack = 0,
    },
    [1701202] = {
        id = 1701202,
        text = "Es ist Weihnachten! Fragst du dich, was sich unter diesem Rock befindet?",
        minipack = 0,
    },
    [1701203] = {
        id = 1701203,
        text = "Frohe Weihnachten~ Findest du diese Mütze niedlich?",
        minipack = 0,
    },
    [1701204] = {
        id = 1701204,
        text = "Es schneit draußen! Wie wäre es damit, den Schnee mit mir zu beobachten?",
        minipack = 0,
    },
    [1701205] = {
        id = 1701205,
        text = "Ara, ara, der Weihnachtsmann wird bösen Kindern keinen Besuch abstatten?",
        minipack = 0,
    },
    [1701206] = {
        id = 1701206,
        text = "Ich brauche kein Weihnachtsgeschenk, dich hier zu haben ist gut genug~",
        minipack = 0,
    },
    [1701207] = {
        id = 1701207,
        text = "Oh?... in was soll ich dich verwandeln?",
        minipack = 0,
    },
    [1701208] = {
        id = 1701208,
        text = "Du bist wirklich ein rücksichtsloser kleiner Junge~",
        minipack = 0,
    },
    [1701209] = {
        id = 1701209,
        text = "Soll ich dir ein paar Manieren beibringen?",
        minipack = 0,
    },
    [1701210] = {
        id = 1701210,
        text = "Wie erwartet, ist dies für dich anziehend~",
        minipack = 0,
    },
    [1701211] = {
        id = 1701211,
        text = "Kannst du dich nicht mehr zurückhalten~",
        minipack = 0,
    },
    [1701212] = {
        id = 1701212,
        text = "Willst du es so gerne anfassen?",
        minipack = 0,
    },
    [1701213] = {
        id = 1701213,
        text = "Haha~ Komm und fühle diesen perfekten Körper~",
        minipack = 0,
    },
    [1701214] = {
        id = 1701214,
        text = "Kannst du aufhören, mich anzufassen? Meine Haare sind sowieso kraus...",
        minipack = 0,
    },
    [1701215] = {
        id = 1701215,
        text = "Wow...!? Was machst du da? Beängstigend...",
        minipack = 0,
    },
    [1701216] = {
        id = 1701216,
        text = "Es wird mich schön machen...? Wovon redest du?",
        minipack = 0,
    },
    [1701217] = {
        id = 1701217,
        text = "Bist du sicher, dass das funktionieren wird? Nicht nötig, sich zu verwandeln?",
        minipack = 0,
    },
    [1701218] = {
        id = 1701218,
        text = "Ich sagte, du musst nichts tun... Nein, du kannst es immer noch tun...",
        minipack = 0,
    },
    [1701219] = {
        id = 1701219,
        text = "Sehe ich jetzt besser aus? Wirklich?",
        minipack = 0,
    },
    [1701220] = {
        id = 1701220,
        text = "Willst du... mit mir auf ein Date gehen?",
        minipack = 0,
    },
    [1701221] = {
        id = 1701221,
        text = "Betrachte es als Warnung",
        minipack = 0,
    },
    [1701222] = {
        id = 1701222,
        text = "Ich erinnere mich nicht, dir erlaubt zu haben, mich zu berühren",
        minipack = 0,
    },
    [1701223] = {
        id = 1701223,
        text = "Geschöpfe wie Geister sollten in dieser Welt nicht existieren.",
        minipack = 0,
    },
    [1701224] = {
        id = 1701224,
        text = "Glaubst du an eine schicksalhafte Begegnung?",
        minipack = 0,
    },
    [1701225] = {
