    [1701486] = {
        id = 1701486,
        text = "Kukuku, lass den Avatar des Windes bis zum Ende der Hölle führen.",
        minipack = 0,
    },
    [1701487] = {
        id = 1701487,
        text = "Ah~ Ich bin so glücklich~... Hust, sogar der Wind scheint zu tanzen!",
        minipack = 0,
    },
    [1701488] = {
        id = 1701488,
        text = "Du hast mich durchschaut? Hast du deine magischen Augen verstärkt?",
        minipack = 0,
    },
    [1701489] = {
        id = 1701489,
        text = "Ich danke dir heute... *Hust*, das Abenteuer ist wunderbar. Lade mich das nächste Mal wieder ein.",
        minipack = 0,
    },
    [1701490] = {
        id = 1701490,
        text = "Sorry, ich habe die Atmosphäre nicht verstanden.",
        minipack = 0,
    },
    [1701491] = {
        id = 1701491,
        text = "Das ist wahrscheinlicher, freu dich einfach darauf!",
        minipack = 0,
    },
    [1701492] = {
        id = 1701492,
        text = "Ja... *Hust*, es ist okay, geh einfach und opfere dich für deinen Glauben.",
        minipack = 0,
    },
    [1701493] = {
        id = 1701493,
        text = "Kein Problem. Ich kenne mich gut mit Kleidung aus!",
        minipack = 0,
    },
    [1701494] = {
        id = 1701494,
        text = "Komm, mach mir dein Kompliment! (altmodischer, Chunibyo-Ton)",
        minipack = 0,
    },
    [1701495] = {
        id = 1701495,
        text = "Diese hier! Er passt perfekt zum schwarzen Speer, wunderbar!",
        minipack = 0,
    },
    [1701496] = {
        id = 1701496,
        text = "Mein Verwandter, warum bist du hier?",
        minipack = 0,
    },
    [1701497] = {
        id = 1701497,
        text = "Hey... willst du nicht etwas sagen?... mach es nicht so unangenehm.",
        minipack = 0,
    },
    [1701498] = {
        id = 1701498,
        text = "Ähm, du hast Opfergaben vorbereitet. Das ist sehr rücksichtsvoll. ... Wow, was ist das, super lecker!",
        minipack = 0,
    },
    [1701499] = {
        id = 1701499,
        text = "Interessant. Als Belohnung gebe ich dir die Hälfte der Welt.",
        minipack = 0,
    },
    [1701500] = {
        id = 1701500,
        text = "Danke für deine Mühen. Ich kann dich loben. (Antiker, Chunibyo-Ton)...Was? Nein, ich meine es sehr ernst!",
        minipack = 0,
    },
    [1701501] = {
        id = 1701501,
        text = "Kuku, schöne Opfergaben, du hast es gut gemacht.",
        minipack = 0,
    },
    [1701502] = {
        id = 1701502,
        text = "Hhmm, ich habe \"Karma\" angesammelt... (altmodischer, Chunibyo-Ton) Was? Das ist nicht nötig? Was meinst du damit? (Jugendton)",
        minipack = 0,
    },
    [1701503] = {
        id = 1701503,
        text = "Mein Verwandter, warum beschwörst du mich?",
        minipack = 0,
    },
    [1701504] = {
        id = 1701504,
        text = "Vielleicht werde ich Yuzuru das nächste Mal besiegen!",
        minipack = 0,
    },
    [1701505] = {
        id = 1701505,
        text = "Kuku, gut, ich werde mich eine Weile mit dir unterhalten. Du solltest dich geehrt fühlen. (Hinweis: Antiker, Chunibyo-Ton)",
        minipack = 0,
    },
    [1701506] = {
        id = 1701506,
        text = "Avatar des Windes - Kaguya Yamai ist hier! (Antiker, Chunibyo-Ton)",
        minipack = 0,
    },
    [1701507] = {
        id = 1701507,
        text = "Kukuku! Ich bin nicht aufzuhalten! (altmodischer, Chunibyo-Ton)",
        minipack = 0,
    },
    [1701508] = {
        id = 1701508,
        text = "Willst du mein Geschick sehen?",
        minipack = 0,
    },
    [1701509] = {
        id = 1701509,
        text = "Lass uns kämpfen, Yuzuru!",
        minipack = 0,
    },
    [1701510] = {
        id = 1701510,
        text = "Schau nach vorne. Welchen Unfall werde ich antreffen?",
        minipack = 0,
    },
    [1701511] = {
        id = 1701511,
        text = "Lob. Sehr angenehmes Date.",
        minipack = 0,
    },
    [1701512] = {
        id = 1701512,
        text = "Überrascht. [Du hast mich erwischt] (Emotionslos).",
        minipack = 0,
    },
    [1701513] = {
        id = 1701513,
        text = "Angenehm. Hätte nie gedacht, dass es so interessant sein würde.",
        minipack = 0,
    },
    [1701514] = {
        id = 1701514,
        text = "Fehleinschätzung. Yuzuru hatte es zu eilig.",
        minipack = 0,
    },
    [1701515] = {
        id = 1701515,
        text = "Erfolgreich. Alles läuft wie geplant.",
        minipack = 0,
    },
    [1701516] = {
        id = 1701516,
        text = "Verstanden. Ich werde dich nochmal einladen.",
        minipack = 0,
    },
    [1701517] = {
        id = 1701517,
        text = "Einverstanden. Ich frage mich, welche Art von Kleidung du für Yuzuru auswählen wirst.",
        minipack = 0,
    },
    [1701518] = {
        id = 1701518,
        text = "Frage. Hat Kaguya auch diese Kleidung?",
        minipack = 0,
    },
    [1701519] = {
        id = 1701519,
        text = "Wunderbar. Kaguya wird es mit einem dieser ausgefallenen Worte beschreiben.",
        minipack = 0,
    },
    [1701520] = {
        id = 1701520,
        text = "Kariös. Was willst du mit Yuzuru an so einem Ort machen?",
        minipack = 0,
    },
    [1701521] = {
        id = 1701521,
        text = "Bereithalten. Eintritt in den Energiesparmodus.",
        minipack = 0,
    },
    [1701522] = {
        id = 1701522,
        text = "Lob. Selbst im Paradies ist es schwer, diese Art von köstlichem Essen zu finden.",
        minipack = 0,
    },
    [1701523] = {
        id = 1701523,
        text = "Annehmbar. Da es von dir ist, werde ich mich nicht zurückhalten.",
        minipack = 0,
    },
    [1701524] = {
        id = 1701524,
        text = "Hinweisen. Wenn Mädchen sagen [es ist so schön], must du antworten [du bist schöner].",
        minipack = 0,
    },
    [1701525] = {
        id = 1701525,
        text = "Gefällt mir. Danke, ich bin glücklich.",
        minipack = 0,
    },
    [1701526] = {
        id = 1701526,
        text = "Verwöhnen. Das Bond ist verstärkt",
        minipack = 0,
    },
    [1701527] = {
        id = 1701527,
        text = "Anfrage. Hast du Zeit für ein kaltes Getränk?",
        minipack = 0,
    },
    [1701528] = {
        id = 1701528,
        text = "Verstärken. Ressourcen für nutzlose Personen verschwenden? Wie Kagu-",
        minipack = 0,
    },
    [1701529] = {
        id = 1701529,
        text = "Frage. Warum starrst du Yuzuru an?",
        minipack = 0,
    },
    [1701530] = {
        id = 1701530,
        text = "Vorsicht. Es liegt ein Geruch von Gefahr in der Luft.",
        minipack = 0,
    },
    [1701531] = {
        id = 1701531,
        text = "Stolz. Yuzuru ist stärker geworden.",
        minipack = 0,
    },
    [1701532] = {
        id = 1701532,
        text = "Anzeigen. Welche Daten möchtest du überprüfen, oder möchtest du etwas anderes als Daten?",
        minipack = 0,
    },
    [1701533] = {
        id = 1701533,
        text = "Wettbewerb. Kaguya, Yuzuru wird diesmal ihr Bestes versuchen.",
        minipack = 0,
    },
    [1701534] = {
        id = 1701534,
        text = "*Unterschreiben* Tut mir leid, ich habe kein Interesse an Kindern.",
        minipack = 0,
    },
    [1701535] = {
        id = 1701535,
        text = "Ich hätte nie gedacht, dass dies mehr Spaß machen würde als zu kämpfen.",
        minipack = 0,
    },
    [1701536] = {
        id = 1701536,
        text = "Hhmm, gute Leistung.",
        minipack = 0,
    },
    [1701537] = {
        id = 1701537,
        text = "So fühlt sich also ein Date an? Scheint interessant zu sein.",
        minipack = 0,
    },
    [1701538] = {
        id = 1701538,
        text = "Langweilig - langweilig - bitte mich nicht, das nochmal zu tun.",
        minipack = 0,
    },
    [1701539] = {
        id = 1701539,
        text = "Vergiss nicht, pünktlich zu kommen, das ist ein Befehl.",
        minipack = 0,
    },
    [1701540] = {
        id = 1701540,
        text = "Wie kannst du es wagen, mich zurückzuweisen? (Bedrohlich)",
        minipack = 0,
    },
    [1701541] = {
        id = 1701541,
        text = "Neue Kampfpanzerung?",
        minipack = 0,
    },
    [1701542] = {
        id = 1701542,
        text = "Wie nervig... warum muss ich diese Art von Kleidung anziehen",
        minipack = 0,
    },
    [1701543] = {
        id = 1701543,
        text = "Wie erwartet, macht gewöhnliche Kleidung nicht so viel Spaß wie eine Panzerung.",
        minipack = 0,
    },
    [1701544] = {
        id = 1701544,
        text = "Gibt es neue Waffen?",
        minipack = 0,
    },
    [1701545] = {
        id = 1701545,
        text = "Zeig mir, was du drauf hast.",
        minipack = 0,
    },
    [1701546] = {
        id = 1701546,
        text = "Hähh. Na ja, nicht schlecht. Danke für deine Mühen. Verlassen.",
        minipack = 0,
    },
    [1701547] = {
        id = 1701547,
        text = "Es ist nicht schlecht, aber ein bisschen Kreativität wäre vielleicht ganz nett.",
        minipack = 0,
    },
    [1701548] = {
        id = 1701548,
        text = "Hähh...? Es sieht anders aus. Ich kann es akzeptieren. Aber versteh das nicht falsch.",
        minipack = 0,
    },
    [1701549] = {
        id = 1701549,
        text = "Was ist das? Wenn du mich zufriedenstellen willst, mach ein paar Nachforschungen.",
        minipack = 0,
    },
    [1701550] = {
        id = 1701550,
        text = "Naja... Von jemandem wie dir gelobt zu werden, wird mich nicht glücklich machen",
        minipack = 0,
    },
    [1701551] = {
        id = 1701551,
        text = "Ich bin der stärkste Zauberer!",
        minipack = 0,
    },
    [1701552] = {
        id = 1701552,
        text = "Gerade rechtzeitig, um meine neue Ausrüstung zu testen.",
        minipack = 0,
    },
    [1701553] = {
        id = 1701553,
        text = "Was ist los? Wenn es nichts ist, könntest du mich dann in Ruhe lassen?",
        minipack = 0,
    },
    [1701554] = {
        id = 1701554,
        text = "Überlasse es einfach dem mächtigsten Charakter: mir.",
        minipack = 0,
    },
    [1701555] = {
        id = 1701555,
        text = "Weil ich der Stärkste bin.",
        minipack = 0,
    },
    [1701556] = {
        id = 1701556,
        text = "Yeah! Das bin ich in Höchstform!",
        minipack = 0,
    },
    [1701557] = {
        id = 1701557,
        text = "Mal sehen, wer sich mir in den Weg stellen kann!",
        minipack = 0,
    },
    [1701558] = {
        id = 1701558,
        text = "Emhehe, wohin bringst du mich?",
        minipack = 0,
    },
    [1701559] = {
        id = 1701559,
        text = "Darling ist der Beste~ Ich bin heute super glücklich.",
        minipack = 0,
    },
    [1701560] = {
        id = 1701560,
        text = "Ich mag Darling am liebsten~",
        minipack = 0,
    },
    [1701561] = {
        id = 1701561,
        text = "Du wirst lernen, geduldig zu sein, Darling.",
        minipack = 0,
    },
    [1701562] = {
        id = 1701562,
        text = "Die heutige \"Party\" verlief reibungslos.",
        minipack = 0,
    },
    [1701563] = {
        id = 1701563,
        text = "Muss ich zur Erinnerung einen Anruf machen? Darling, komm nicht zu spät.",
        minipack = 0,
    },
    [1701564] = {
        id = 1701564,
        text = "Warum? Du willst mich nicht singen hören? (gekränkt, weinend)",
        minipack = 0,
    },
    [1701565] = {
        id = 1701565,
        text = "Willst du mich in dem neuen Kostüm sehen?",
        minipack = 0,
    },
    [1701566] = {
        id = 1701566,
        text = "Gute Reaktion! Bist du von mir fasziniert?",
        minipack = 0,
    },
    [1701567] = {
        id = 1701567,
        text = "Darling, schau mal, wie ist dieses Kostüm?",
        minipack = 0,
    },
    [1701568] = {
        id = 1701568,
        text = "Darling, du hast ein Geschenk für mich? Ich bin so glücklich!",
        minipack = 0,
    },
    [1701569] = {
        id = 1701569,
        text = "Darling, du hast ein Geschenk für mich? Ich freue mich darauf.",
        minipack = 0,
    },
    [1701570] = {
        id = 1701570,
        text = "Hm! So lecker! Ich spüre Darlings Liebe darin.",
        minipack = 0,
    },
    [1701571] = {
        id = 1701571,
        text = "Ara~ Es sieht lecker aus. Kann ich es akzeptieren?",
        minipack = 0,
    },
    [1701572] = {
        id = 1701572,
        text = "Wow~! Danke dir~! Um dieses Geschenk zu erwidern, kann ich dir eine Umarmung geben~!",
        minipack = 0,
    },
    [1701573] = {
        id = 1701573,
        text = "Danke~ Ich werde es in Ehren halten~~!",
        minipack = 0,
    },
    [1701574] = {
        id = 1701574,
        text = "Darling, ich mag dich so sehr!",
        minipack = 0,
    },
    [1701575] = {
        id = 1701575,
        text = "Lalala, Darling, willst du mich singen hören?",
        minipack = 0,
    },
    [1701576] = {
        id = 1701576,
        text = "Ich meine es ernst. Wie können sie es wagen, unser Date zu stören! Wie nervig, hhmm~",
        minipack = 0,
    },
    [1701577] = {
        id = 1701577,
        text = "Ich meine, du bekommst mein Autogramm nicht, wenn du mich so anstarrst.",
        minipack = 0,
    },
    [1701578] = {
        id = 1701578,
        text = "Hallo~ Danke, dass du mich gefragt hast, Darling. Ich bin deine Miku!",
        minipack = 0,
    },
    [1701579] = {
        id = 1701579,
        text = "Ich kann jetzt noch besser singen~!",
        minipack = 0,
    },
    [1701580] = {
        id = 1701580,
        text = "Der Kampf ist nichts für Damen, aber für Darling kann ich alles tun.",
        minipack = 0,
    },
    [1701581] = {
        id = 1701581,
        text = "Darling, lass mich dich schützen!",
        minipack = 0,
    },
    [1701582] = {
        id = 1701582,
        text = "Es ist, als wäre ich in einem Traum. Wie alle anderen kann ich mich jetzt mit dir auf Dates gehen.",
        minipack = 0,
    },
    [1701583] = {
        id = 1701583,
        text = "Hehe, ich hätte nie gedacht, dass ich so glücklich sein würde.",
        minipack = 0,
    },
    [1701584] = {
        id = 1701584,
        text = "Ara, du hast mich erwischt, hehe.",
        minipack = 0,
    },
    [1701585] = {
        id = 1701585,
        text = "Egal, wie oft ich gekommen bin, ich genieße diesen Ort immer wieder.",
        minipack = 0,
    },
    [1701586] = {
        id = 1701586,
        text = "Keine Eile, lass dir Zeit.",
        minipack = 0,
    },
    [1701587] = {
        id = 1701587,
        text = "Bis später dann, ich freue mich darauf.",
        minipack = 0,
    },
    [1701588] = {
        id = 1701588,
        text = "Es ist OK. Lass uns das nächste Mal hart arbeiten.",
        minipack = 0,
    },
    [1701589] = {
        id = 1701589,
        text = "Bekleidungsgeschäft? Viele lustige Erinnerungen dort, hehe.",
        minipack = 0,
    },
    [1701590] = {
        id = 1701590,
        text = "Passt es?... Hehe, ich bin froh, dass es dir gefällt",
        minipack = 0,
    },
    [1701591] = {
        id = 1701591,
        text = "Dieses Kleid ist so hübsch. Gefalle ich dir jetzt besser?",
        minipack = 0,
    },
    [1701592] = {
        id = 1701592,
        text = "Hm? Hast du dich hereingeschlichen, um mich zu finden? Hehe~",
        minipack = 0,
    },
    [1701593] = {
        id = 1701593,
        text = "Oh, willst du mir ein Geschenk machen?",
        minipack = 0,
    },
    [1701594] = {
        id = 1701594,
        text = "Dieser Geschmack... Ich habe es noch nie geschmeckt",
        minipack = 0,
    },
    [1701595] = {
        id = 1701595,
        text = "Vielen Dank, es ist wirklich köstlich.",
        minipack = 0,
    },
    [1701596] = {
        id = 1701596,
        text = "Ich bin so glücklich, dass du immer weißt, was ich mag.",
        minipack = 0,
    },
    [1701597] = {
        id = 1701597,
        text = "Wirklich! Ist es wirklich für mich?",
        minipack = 0,
    },
    [1701598] = {
        id = 1701598,
        text = "Wie immer liebe ich dich von ganzem Herzen... War nur ein Scherz",
        minipack = 0,
    },
    [1701599] = {
        id = 1701599,
        text = "Hast du mich vermisst? Es ist ok, ich werde hier sein.",
        minipack = 0,
    },
    [1701600] = {
        id = 1701600,
        text = "Ich spüre die Stärke von allen.",
        minipack = 0,
    },
    [1701601] = {
        id = 1701601,
        text = "?Was ist los?",
        minipack = 0,
    },
    [1701602] = {
        id = 1701602,
        text = "Ich bin der Preisrichter. Ich werde - dich durchschauen.",
        minipack = 0,
    },
    [1701603] = {
        id = 1701603,
        text = "Dann... Ich kann dich schützen.",
        minipack = 0,
    },
    [1701604] = {
        id = 1701604,
        text = "Im Vergleich zu anderen bin ich nicht gut genug.",
        minipack = 0,
    },
    [1701605] = {
        id = 1701605,
        text = "Für den, den ich liebe, werde ich mein Bestes tun.",
        minipack = 0,
    },
