    },
    [1701991] = {
        id = 1701991,
        text = "Ha, Date...? Mit mir? Ist das dein Ernst?",
        minipack = 0,
    },
    [1701992] = {
        id = 1701992,
        text = "Was würden wir heute tun?",
        minipack = 0,
    },
    [1701993] = {
        id = 1701993,
        text = "Du bist irgendwie knallhart...",
        minipack = 0,
    },
    [1701994] = {
        id = 1701994,
        text = "Date... klingt lustig... nein, nichts.",
        minipack = 0,
    },
    [1701995] = {
        id = 1701995,
        text = "Was zur Hölle...",
        minipack = 0,
    },
    [1701996] = {
        id = 1701996,
        text = "Wenn du ablehnen willst, sag es jetzt. Ist das wirklich erlaubt?",
        minipack = 0,
    },
    [1701997] = {
        id = 1701997,
        text = "Ah, gut, das wollte ich meinen. Ich bin überhaupt nicht verärgert. Das ist nur normal.",
        minipack = 0,
    },
    [1701998] = {
        id = 1701998,
        text = "Ich meine, es gibt nichts, was sich lohnt anzuschauen.",
        minipack = 0,
    },
    [1701999] = {
        id = 1701999,
        text = "Also gibst du mir keine Kleidung mehr...",
        minipack = 0,
    },
    [1702000] = {
        id = 1702000,
        text = "Danke... sehe ich... hübsch aus?",
        minipack = 0,
    },
    [1702001] = {
        id = 1702001,
        text = "Meine Güte, was ist das denn? Oh? Ein Geschenk für mich?",
        minipack = 0,
    },
    [1702002] = {
        id = 1702002,
        text = "Wenn du aufhören willst, dann tu es einfach. Es ist besser, es anderen Mädchen zu geben...",
        minipack = 0,
    },
    [1702003] = {
        id = 1702003,
        text = "Wow, so lecker, was ist das?... Danke- vielen Dank.",
        minipack = 0,
    },
    [1702004] = {
        id = 1702004,
        text = "Es geht so.",
        minipack = 0,
    },
    [1702005] = {
        id = 1702005,
        text = "Wow, erstaunlich...",
        minipack = 0,
    },
    [1702006] = {
        id = 1702006,
        text = "Hhmm, na ja, nicht schlecht.",
        minipack = 0,
    },
    [1702007] = {
        id = 1702007,
        text = "... Nein, nun, es ist nicht schlecht, oder?",
        minipack = 0,
    },
    [1702008] = {
        id = 1702008,
        text = "Darf ich das wirklich tun?",
        minipack = 0,
    },
    [1702009] = {
        id = 1702009,
        text = "Was?! Ein interessantes Spiel beginnt gleich?",
        minipack = 0,
    },
    [1702010] = {
        id = 1702010,
        text = "Was ist los? Hört auf zu nörgeln und zu jammern.",
        minipack = 0,
    },
    [1702011] = {
        id = 1702011,
        text = "Ich werde dein Leben ruinieren!",
        minipack = 0,
    },
    [1702012] = {
        id = 1702012,
        text = "Wenn es nicht viel besser ist, gib nicht mir die Schuld.",
        minipack = 0,
    },
    [1702013] = {
        id = 1702013,
        text = "Ich bin... dabei",
        minipack = 0,
    },
    [1702014] = {
        id = 1702014,
        text = "Nur ich kann ihm einen Streich spielen!",
        minipack = 0,
    },
