    [1702053] = {
        id = 1702053,
        text = "[Haupt] Natsumi_Kapitel 1",
        minipack = 0,
    },
    [1702054] = {
        id = 1702054,
        text = "Das Dienstmädchen mit dem Haar so dunkel wie die Nacht, hat Augen so hell wie Sterne am Himmel.",
        minipack = 0,
    },
    [1702055] = {
        id = 1702055,
        text = "Selbst die Identität als starke Kriegerin kann ihr mädchenhaftes Herz nicht verbergen.",
        minipack = 0,
    },
    [1702056] = {
        id = 1702056,
        text = "Mit einem Herzen so zerbrechlich wie Glas, hat sie Angst vor Fremden und braucht deine Fürsorge.",
        minipack = 0,
    },
    [1702057] = {
        id = 1702057,
        text = "Mächtige und grausame Stärke, mit noch tödlicherer Schönheit.",
        minipack = 0,
    },
    [1702058] = {
        id = 1702058,
        text = "Sie versucht die ganze Zeit, ruhig zu bleiben. Sie verliert sich jedoch immer in der Wärme ihres Bruders.",
        minipack = 0,
    },
    [1702059] = {
        id = 1702059,
        text = "[Liebe] ist der einzige Grund ihrer Existenz. Sie bleibt an der Spitze wie ein Engel.",
        minipack = 0,
    },
    [1702060] = {
        id = 1702060,
        text = "Sie offenbart ihr wahres Selbst nur denen, denen sie vertraut.",
        minipack = 0,
    },
    [1702061] = {
        id = 1702061,
        text = "Valentinstag? Umu... Solange ich mit dir auf ein Date gehen kann, ist es ein guter Tag für mich. \nMit mir zusammen zu sein, macht dich auch glücklich, richtig?",
        minipack = 0,
    },
    [1702062] = {
        id = 1702062,
        text = "Liebe Geliebte, ich hoffe, du nimmst meine Blumen und meinen Liebesbrief an. \nKomm, verbringe die schöne Nacht mit mir!",
        minipack = 0,
    },
    [1702063] = {
        id = 1702063,
        text = "Yoshino ist bereits stärker als zuvor...\nFro- Frohen Valentinstag~",
        minipack = 0,
    },
    [1702064] = {
        id = 1702064,
        text = "Ara, auch wenn es so vorherbestimmt war, fühle ich mich manchmal immer noch glücklich~\ndass ich dich im Fluss der Zeit getroffen habe.",
        minipack = 0,
    },
    [1702065] = {
        id = 1702065,
        text = "Dummer großer Bruder, dieses Festival ist für Verliebte, aber ich habe dir etwas zu sagen. \nDanke, dass du die ganze Zeit für mich da warst.",
        minipack = 0,
    },
    [1702066] = {
        id = 1702066,
        text = "Heute werde ich deine Hand halten, um über die blühende Ebene zu gehen oder unter dem Blütenblätter regnenden Wald. \nBis unser Schatten im Licht des Sonnenuntergangs länger wird.",
        minipack = 0,
    },
    [1702067] = {
        id = 1702067,
        text = "Eigentlich möchte ich manchmal ehrlich zu dir sein... \nAber ich warte auf das perfekte Timing.",
        minipack = 0,
    },
