    [1702121] = {
        id = 1702121,
        text = "Mu~ was machst du da...",
        minipack = 0,
    },
    [1702122] = {
        id = 1702122,
        text = "Wow! Mach- mach keine Witze! Verschwinde einfach!",
        minipack = 0,
    },
    [1702123] = {
        id = 1702123,
        text = "Hhmm, hhmm, hhmm, mir kannst du nichts vormachen. Außer meinen eigenen Worten werde ich nichts glauben.",
        minipack = 0,
    },
    [1702124] = {
        id = 1702124,
        text = "Ist das wahr?... Auch wenn ich meine Stimme verliere, wirst du immer noch mein Fan sein?",
        minipack = 0,
    },
    [1702125] = {
        id = 1702125,
        text = "Was? Plötzlich willst du mich singen hören? Hehe, jederzeit~",
        minipack = 0,
    },
    [1702126] = {
        id = 1702126,
        text = "Ach, tu das nicht, Darling. Fortsetzung folgt~",
        minipack = 0,
    },
    [1702127] = {
        id = 1702127,
        text = "Dir gefällt es hier? *Seufz*... dann gibt es keinen anderen Weg~",
