    },
    [1702146] = {
        id = 1702146,
        text = "Ohoh! Sehe ich süß aus? Dies ist das erste Mal, dass ich solche Kleidung trage.",
        minipack = 0,
    },
    [1702147] = {
        id = 1702147,
        text = "Schau! Seidig und weich, so angenehm!",
        minipack = 0,
    },
    [1702148] = {
        id = 1702148,
        text = "Umu, es ist schwer, in diesem Tuch zu gehen...",
        minipack = 0,
    },
    [1702149] = {
        id = 1702149,
        text = "Ähm! Das Kleid ist dabei, herunterzufallen! Hilf mir dabei!",
        minipack = 0,
    },
    [1702150] = {
        id = 1702150,
        text = "Schau, ein Sakura-Kopfschmuck, ist der nicht hübsch?",
