    },
    [1702151] = {
        id = 1702151,
        text = "Umu... Ohne Unterwäsche fühlt es sich ungemütlich an...",
        minipack = 0,
    },
    [1702152] = {
        id = 1702152,
        text = "Umu... Es scheint, ich habe zu viel gegessen, der Gürtel ist zu eng... Ähm, kannst du mich auf deinem Rücken tragen?",
        minipack = 0,
    },
    [1702153] = {
        id = 1702153,
        text = "Ich habe meine Haarnadel mit einer besondere Kopfschmuckblume ersetzt. Sieht es hübsch aus?",
        minipack = 0,
    },
    [1702154] = {
        id = 1702154,
        text = "Unterwäsche ist nicht notwendig, wenn du einen Kimono trägst.",
        minipack = 0,
    },
    [1702155] = {
        id = 1702155,
        text = "Vielen Dank für dein Geschenk. Ich bin sehr glücklich.",
        minipack = 0,
    },
    [1702156] = {
        id = 1702156,
        text = "Im Vergleich zum Tragen bin ich besser darin, sie auszuziehen.",
        minipack = 0,
    },
    [1702157] = {
        id = 1702157,
        text = "Lass uns gemeinsam den Schrein besuchen.",
        minipack = 0,
    },
    [1702158] = {
