    },
    [1702395] = {
        id = 1702395,
        text = "Erinnerung",
        minipack = 0,
    },
    [1702396] = {
        id = 1702396,
        text = "Alle diesmal vorgenommenen Änderungen abbrechen?",
        minipack = 0,
    },
    [1702397] = {
        id = 1702397,
        text = "Mama, hier gibt es einen seltsamen Ojisan!",
        minipack = 0,
    },
    [1702398] = {
        id = 1702398,
        text = "Tsk, der geschrumpfte Körper ist wirklich unpraktisch...",
        minipack = 0,
    },
    [1702399] = {
        id = 1702399,
        text = "Ich muss ins Badezimmer gehen. Aber ich kann es nicht selbst tun.",
        minipack = 0,
    },
    [1702400] = {
        id = 1702400,
        text = "Ich will Kekse. Füttere mich.",
        minipack = 0,
    },
    [1702401] = {
        id = 1702401,
        text = "Mein Name ist Chiyogami. Freut mich, dich kennenzulernen.",
        minipack = 0,
    },
    [1702402] = {
        id = 1702402,
        text = "Ich bin die Frucht der Liebe meiner Eltern.",
        minipack = 0,
    },
    [1702403] = {
        id = 1702403,
        text = "Papa, mach keine Dummheiten.",
        minipack = 0,
    },
    [1702404] = {
        id = 1702404,
        text = "Klasse 3A",
        minipack = 0,
    },
    [1702405] = {
        id = 1702405,
        text = "Chiyogami Itsuka",
        minipack = 0,
    },
    [1702406] = {
        id = 1702406,
        text = "Selbst das kleinste Haus muss einen breiten Eingang haben, um Besuchern Höflichkeit zu zeigen. Es ist auch der Ort, an dem eine \"besondere Interaktion\" mit den Geistern stattfinden könnte!",
        minipack = 0,
    },
    [1702407] = {
        id = 1702407,
        text = "",
        minipack = 0,
    },
    [1702408] = {
        id = 1702408,
        text = "",
        minipack = 0,
    },
    [1702409] = {
        id = 1702409,
        text = "",
        minipack = 0,
    },
    [1702410] = {
        id = 1702410,
        text = "",
        minipack = 0,
    },
    [1702411] = {
        id = 1702411,
        text = "An average home. This angle is great.",
        minipack = 0,
    },
    [1702412] = {
        id = 1702412,
        text = "",
        minipack = 0,
    },
    [1702413] = {
        id = 1702413,
        text = "",
        minipack = 0,
    },
    [1702414] = {
        id = 1702414,
        text = "",
        minipack = 0,
    },
    [1702415] = {
        id = 1702415,
        text = "",
        minipack = 0,
    },
    [1702416] = {
        id = 1702416,
        text = "Während des Baus dieses Apartments wollte Kotori, dass die Geister in einer pinken Welt leben. Selbst die stolze Kurumi hat eine zarte Seite, nicht wahr? (Auch wenn sie letztendlich nicht hier wohnt^0^)",
        minipack = 0,
    },
    [1702417] = {
        id = 1702417,
        text = "Um mehr über das tägliche Leben des Geistes zu erfahren, besuche öfter ihr Wohnzimmer. Vielleicht erhältst du sogar einen besonderen \"Service\".",
        minipack = 0,
    },
    [1702418] = {
        id = 1702418,
        text = "Hier schlafen die Geister nachts. Ich hoffe, das Zimmer mit nächtlicher Aussicht auf Tengu-Stadt wird ihnen einen romantischen Traum bescheren.",
        minipack = 0,
    },
    [1702419] = {
        id = 1702419,
        text = "Jede Nacht hört man im Wohnzimmer, in dem die Geister leben, wenn der Fernseher läuft, mit Sicherheit Yoshinons Weinen und Natsumis Schreien. Das bedeutet, dass das Drama läuft.",
        minipack = 0,
    },
    [1702420] = {
        id = 1702420,
        text = "",
        minipack = 0,
    },
    [1702421] = {
        id = 1702421,
        text = "",
        minipack = 0,
    },
    [1702422] = {
        id = 1702422,
        text = "Selbst das hellste Sonnenlicht kann die Finsternis im Herzen des Geistes nicht vertreiben. Warum muss ein Geist sitzen und den Lehrern zuhören? Was für eine Qual.",
        minipack = 0,
    },
    [1702423] = {
        id = 1702423,
        text = "Faule Schüler werden sich manchmal auf dem leeren Dach versammeln. Manche behaupten, sie hätten einmal ein mysteriöses Mädchen in Rot mit einem unvergesslich schönen Gesicht gesehen.",
        minipack = 0,
    },
    [1702424] = {
        id = 1702424,
        text = "Der Korridor kann freche Schüler an die stehende Strafe erinnern. Zwischen den Klassen wird es ziemlich ruppig, oh wie die gute Zeit vergeht...",
        minipack = 0,
    },
    [221001] = {
        id = 221001,
        text = "Date-Daten existieren nicht",
        minipack = 0,
    },
    [1702426] = {
        id = 1702426,
        text = "Man sagt, dies sei der beste Ort, um den Mond zu bewundern. Aber nur wenige würden nachts hierher kommen, oder? Wenn du den Schatten eines einsamen Mädchens siehst, sei nicht allzu überrascht.",
        minipack = 0,
    },
    [1702427] = {
        id = 1702427,
        text = "Der Korridor ist nachts ruhig, aber kein guter Ort für Dates. Vielleicht mögen nur einige Geister diese Art von Ort.",
        minipack = 0,
    },
    [1702428] = {
        id = 1702428,
        text = "",
        minipack = 0,
    },
    [1702429] = {
        id = 1702429,
        text = "",
        minipack = 0,
