        minipack = 0,
    },
    [221003] = {
        id = 221003,
        text = "Gebäude nicht verfügbar",
        minipack = 0,
    },
    [1702442] = {
        id = 1702442,
        text = "Gefüllt mit dem Geruch verschiedener Delikatessen, gilt es bei Tohka als Paradies. Achte auf deine Brieftasche, sonst ist sie über Nacht leer.",
        minipack = 0,
    },
    [1702443] = {
        id = 1702443,
        text = "Wenn die Nacht hereinbricht, wird es viele spezielle Essen geben. Wenn Essen nicht dein Ding ist, macht das Glitzern es hier immer noch zu einem guten Date-Treffpunkt.",
        minipack = 0,
    },
    [1702444] = {
