    [1702462] = {
        id = 1702462,
        text = "Das gut dekorierte Blumen Laden sieht sehr edel aus. Jedes Mädchen mag hier andere Blumen. Man kann argumentieren, dass dieser einfache Blumenladen tatsächlich das größte Wissen über Dates enthält.",
        minipack = 0,
    },
    [1702463] = {
        id = 1702463,
        text = "Wenn du erschöpft davon bist, die Geister zufrieden zu stellen, komm in den Getränkeladen. Eine Tasse eisige Schokolade macht die Geister glücklich und füllt deine Ausdauer wieder auf.",
        minipack = 0,
    },
    [1702464] = {
        id = 1702464,
        text = "Das Blumen Laden wird wegen seines Duftes nachts von Schmetterlingen besucht. Blumen werden in der Nacht eine andere Date-Erfahrung bringen.",
        minipack = 0,
    },
    [221006] = {
        id = 221006,
