        minipack = 0,
    },
    [1702466] = {
        id = 1702466,
        text = "Ein Glas eisgekühltes Getränk an der Seite eines geliebten Menschen trinken, mit einer Brise in der Nacht... ein Moment wie dieser wird die Müdigkeit des Tages lindern. Dies ist der beste Ort zum Besuchen, bevor man ins Bett geht.",
        minipack = 0,
