        text = "Ich bin Blanc, die Göttin von Lowee. Lesen ist mein Hobby. Mein Ziel ist es, meine Arbeit zu veröffentlichen. Freut mich, dich kennenzulernen.",
        minipack = 0,
    },
    [1702610] = {
        id = 1702610,
        text = "Ähm... was ist da drüben?",
        minipack = 0,
    },
