    [13310517] = {
        id = 13310517,
        text = "Ein bizarres Fragment, durch dessen Oberfläche man Bilder sehen kann. Sammle alle Fragmente, um die CG zu aktivieren.",
        minipack = 0,
    },
    [13310525] = {
        id = 13310525,
        text = "Liebe Paktpartner, \n Wir entschuldigen uns aufrichtig dafür, dass wir den Sicherheitsmechanismus, der das Gleichgewicht zwischen glücklichen und unglücklichen Spielern aufrechterhält, nicht erläutert haben, falls die Regeln zu Missverständnissen unter den Spielern geführt haben. Wir entschuldigen uns aufrichtig für die verursachte Verwirrung. \n Trotz unserer Absicht, benutzerfreundliche Funktionen hinzuzufügen, sind die Ergebnisse aufgrund mangelnder Überlegung und Erklärung sowie der mangelnden Umsetzung nicht wie erwartet. Wir sind noch ein junges Studio und werden versuchen, zu lernen und uns zu verbessern. Wir wissen euer Verständnis und eure Unterstützung zu schätzen!\n - Hot Games",
        minipack = 0,
    },
    [213109] = {
        id = 213109,
        text = "Der stärkste Zauberer von DEM besitzt einen exklusiven silbernen Verwirklicher. Sie kann eine Geister-Front leicht besiegen.",
