    },
    [13310541] = {
        id = 13310541,
        text = "Liebe Paktpartner, \n Ratatoskr hat eine heftige Fluktuation der Geisterkraft festgestellt! Die Analyse sagt, dass sie wahrscheinlich von Mayuri ausgeht!\n Alarmstufe Rot! Alle in Ratatoskr, bereiten sich auf harte Gegner vor. \n Bist du zurückgekommen, Mayuri?\n Ein Designer unter dem Pseudonym D·A·L",
        minipack = 0,
    },
