    },
    [1705297] = {
        id = 1705297,
        text = "Kuroko! Gib mir meine Unterwäsche zurück!!",
        minipack = 0,
    },
    [1705298] = {
        id = 1705298,
        text = "Diese Puppe heißt \"Gekota\"..... Die Chance, sie zu gewinnen, ist nur 1 zu 24!",
