    [2101084] = {
        id = 2101084,
        text = "Im Schließfach sind einige Bücher ordentlich sortiert. Das erste ist C++ auf unmögliche Weise lernen, das nächste ist... egal, du musst sie nicht lesen.",
        minipack = 0,
    },
    [2101086] = {
        id = 2101086,
        text = "In das Schließfach sind viele [|||||] Markierungen eingeritzt, darunter befindet sich eine Linie: Den Überblick über mein verlorenes Haar behalten.",
        minipack = 0,
    },
    [2101088] = {
        id = 2101088,
        text = "Der Vakuumbecher ist mit Wolfsbeeren gefüllt. Und daneben steht ein Stethoskop?",
        minipack = 0,
    },
    [2101090] = {
        id = 2101090,
        text = "Im Schließfach steht eine Box Shampoo. Bawang Shampoo... Klingt vertraut.",
        minipack = 0,
    },
    [2101092] = {
        id = 2101092,
        text = "Der Spruch zum Öffnen des Schließfachs ist darin eingraviert: Schlüssel, der die Mächte der Dunkelheit verbirgt! Enthülle deine wahre Macht vor mir. Ich befehle dir gemäß unserem Vertrag. Löse das Siegel!",
        minipack = 0,
    },
    [2101094] = {
        id = 2101094,
        text = "Notiz des Programmierers: Ich gehe zur Frühlingsfeier mit meiner dummen Waifu Tohka nach Akihabar.",
        minipack = 0,
    },
    [2101096] = {
        id = 2101096,
        text = "Unter vielen Kurzhanteln befindet sich ein Glas Eiweißpulver und eine halbe Banane auf dem Schließfach.",
        minipack = 0,
    },
    [2101098] = {
        id = 2101098,
        text = "Da ist ein Paar Hausschuhe drin. Sie riechen... duftend... warum!?",
        minipack = 0,
    },
    [2101100] = {
        id = 2101100,
        text = "Im Schließfach sind ordentlich Hygieneartikel platziert. Es gibt sogar Gesichtsmasken und Hautpflegeprodukte.",
        minipack = 0,
    },
    [2101102] = {
        id = 2101102,
        text = "Es sieht aus wie ein Liebesbrief, auf dem steht: Ich werde 1001 Ziele schaffen.",
        minipack = 0,
    },
    [2101104] = {
        id = 2101104,
        text = "Die alte Spielkassette hat einen stacheligen Mann in blauem Anzug auf dem Cover, der auf etwas zeigt. Er sieht ziemlich krass aus.",
        minipack = 0,
    },
    [2101106] = {
        id = 2101106,
        text = "Da ist eine Notiz, auf der steht: Ich habe nichts heimlich geändert, ich habe nichts heimlich geändert, ich habe nichts heimlich geändert...",
        minipack = 0,
    },
    [2101108] = {
        id = 2101108,
        text = "Im Schließfach liegt der Modellbausatz eines komischen Mannes. Dort steht: [Ich will nicht mehr leben!]",
        minipack = 0,
    },
    [2101110] = {
        id = 2101110,
        text = "Auf dem Notizbuch steht: X.X Sonnig. Event: Spieler finden 5 Bugs. Lösung: Töte 2 Spieldesigner.",
        minipack = 0,
    },
    [2101112] = {
        id = 2101112,
        text = "Eine zerknitterte pinke Notiz: Lieber Programmierer, kann ich eine Anforderung hinzufügen, nur eine...?",
        minipack = 0,
    },
    [2101114] = {
        id = 2101114,
        text = "Im Schließfach befindet sich eine komplette Date A Live Romanreihe.",
        minipack = 0,
    },
    [2101116] = {
        id = 2101116,
        text = "Da sind zwei unbenutzte Kinokarten vom [21.9.2020]... (Warte, der öffentliche Betatest ging an diesem Tag live!)",
        minipack = 0,
    },
    [2101118] = {
        id = 2101118,
        text = "Es ist mit allen möglichen physischen DAL-Produkten gefüllt. In der Mitte steht eine Zeile, die lautet: \"Hoffentlich wird unser Spiel immer besser und besser!\"",
        minipack = 0,
    },
    [2101120] = {
        id = 2101120,
        text = "\"Meine Waifu ist Kotori und meine Tochter ist Yoshino-chan!\" Slogans wie dieser sind überall auf dem Schließfach zu finden.",
        minipack = 0,
    },
    [2101122] = {
        id = 2101122,
        text = "Es ist vollgestopft mit Gutscheinen für Brathähnchen-Shops. Aber sie sind alle abgelaufen.",
        minipack = 0,
    },
    [2101124] = {
        id = 2101124,
        text = "Das Schließfach ist mit Postern abgedeckt. In der Mitte befinden sich zwei Origami-Poster mit den Zeichen [Engel] und [Teufel].",
        minipack = 0,
    },
    [2101126] = {
        id = 2101126,
        text = "Es ist ein großes Transparent mit der Aufschrift: Wenn deine Waifu ein seltsames Aussehen hat, habe ich sie nicht gezeichnet.",
        minipack = 0,
    },
    [2101128] = {
        id = 2101128,
        text = "Da sind so viele offizielle Date A Live Produkte, einschließlich Modellbausätze, Kunstdrucke und Stehschilder. (Soll ich alles mitnehmen?)",
        minipack = 0,
    },
    [2101130] = {
        id = 2101130,
        text = "Da ist ein Foto drin. Sieht aus, als wäre es von einem berühmten Tänzer einer bestimmten Website signiert?",
        minipack = 0,
    },
    [2101132] = {
        id = 2101132,
        text = "Da ist eine Notiz mit dem Text in Rot [Haare von Boss Jiang]. (Was bedeutet das?)",
        minipack = 0,
    },
    [2101134] = {
        id = 2101134,
        text = "Da ist ein Tagebuch mit benutzten Codewörtern für Mini-Paketen. Eins davon ist nicht durchgekreuzt, es lautet: [Hot Games Pille]",
        minipack = 0,
    },
    [2101136] = {
        id = 2101136,
        text = "Blut im Schließfach kann einen Satz bilden: Dieses Poster ist nicht von uns gezeichnet! [Hoppla, falsche Person!]",
        minipack = 0,
    },
    [2101138] = {
        id = 2101138,
        text = "Es ist eine Namensliste. Es sieht so aus, als würden die Operatoren einige Illustratoren auswählen, die etwas zeichnen, um für das Spiel zu werben.",
        minipack = 0,
    },
    [2101140] = {
