        minipack = 0,
    },
    [2101146] = {
        id = 2101146,
        text = "Im Schließfach befinden sich viele empfindliche Modellbausätze. Aber sie sind alle Drachen?",
        minipack = 0,
    },
    [2101148] = {
        id = 2101148,
        text = "Da ist ein Vakuumbecher ist mit Wolfsbeeren. Sieht aus, als gehöre es einem Mann mittleren Alters.",
        minipack = 0,
    },
    [2101150] = {
