    },
    [1706025] = {
        id = 1706025,
        text = "Ich... hatte heute eine tolle Zeit!",
        minipack = 0,
    },
    [1706026] = {
        id = 1706026,
        text = "Wenn ich weiterhin solche Dates ansammle, werde ich dann irgendwann die wahre Liebe finden?",
        minipack = 0,
    },
    [1706027] = {
        id = 1706027,
        text = "Danke, dass du etwas Zeit mit mir verbringst...",
        minipack = 0,
    },
    [1706028] = {
        id = 1706028,
        text = "Ich freue mich darauf.",
        minipack = 0,
    },
    [1706029] = {
        id = 1706029,
        text = "Es ist in Ordnung, aber du musst das nächste Mal ja sagen, OK?",
        minipack = 0,
    },
    [1706030] = {
        id = 1706030,
        text = "Oh... ist das... wirklich angemessen?",
        minipack = 0,
    },
    [1706031] = {
        id = 1706031,
        text = "Das System hat viele Outfits vorbereitet. DLC...? Was ist das?",
        minipack = 0,
    },
    [1706032] = {
        id = 1706032,
        text = "Das ist das, was du besonders empfiehlst? Ja, ich mag es auch.",
        minipack = 0,
    },
    [1706033] = {
        id = 1706033,
        text = "Hast du heute noch ein Geschenk für mich? Ich kann es kaum erwarten.",
        minipack = 0,
    },
    [1706034] = {
        id = 1706034,
        text = "Was ist... das?",
        minipack = 0,
    },
    [1706035] = {
        id = 1706035,
        text = "(Mampft)... Kann ich noch einen essen?",
        minipack = 0,
    },
    [1706036] = {
        id = 1706036,
        text = "So schmeckt das also...",
