    [10503056] = {
        id = 10503056,
        text = "Hellebarden-Form: \nSchwere Attacke beschwört aufsteigende Flamme. \nDie Flamme verursacht 6 Mal Flammen-SCH in Höhe von 30% ANG. \nKanonen-Form: \nVerstärkt die Zugkraft des schwarzen Feuerballs.",
        minipack = 0,
    },
    [10503064] = {
        id = 10503064,
        text = "Hellebarden-Form: \nDie Flamme verursacht jedes Mal SCH in Höhe von 50% des ANG. Die Flamme verweilt für 3 Sek auf dem Boden. \nDie Flamme auf dem Boden verursacht über 4 Male Flammen-SCH in Höhe von 180% ANG. \nKanonenform: \nKanonen-Form: \nFähigkeit kann direkt ausgelöst werden, ohne aufgeladen zu werden.",
        minipack = 0,
    },
    [10503072] = {
        id = 10503072,
        text = "Hellebarden-Form: \nDie Flamme verursacht jedes Mal SCH in Höhe von 60% des ANG, Reichweite der Flamme auf dem Boden +20%. \nKanonen-Form: \nWenn der schwarze Feuerball explodiert, verursacht er 1 weiteres Mal Schaden, was Flammen-SCH in Höhe von 70% ANG verursacht.",
        minipack = 0,
    },
    [1706143] = {
