        minipack = 0,
    },
    [10503088] = {
        id = 10503088,
        text = "Hellebarden-Form: \nFeuersäulen, die durch einen Sprung ausgelöst werden, werden größer. Diese Fähigkeit verursacht Physischen SCH in Höhe von 770% von Kotoris ANG. \nKanonen-Form: \nExplosionsbereich +20%, Angriffsbereich von Flamme auf dem Boden +20%. Fähigkeitsschaden erhöht. Die Fähigkeit verursacht Flammen-SCH in Höhe von 460% von Kotoris ANG.",
        minipack = 0,
    },
