    },
    [10503104] = {
        id = 10503104,
        text = "In Hellebarden-Form hat Kotori eine Chance von +20%, Ziele bei einem Treffer zu entzünden und Fähigkeit SCH +50%. \n[Entzündete Ziele erleiden jede Sekunde SCH in Höhe von 10% von Kotoris ANG. Dauert 8 Sek. Stapelt bis zu 10 Schichten. Beim max. Stapel entzündet Kotori Ziele mit einer zusätzlichen Flammenexplosion, was in einem kleinen Bereich SCH in Höhe von 30% von Kotoris ANG verursacht. Der Explosionsschaden berechnet die VER der Ziele neu. ]",
        minipack = 0,
    },
