    [13310542] = {
        id = 13310542,
        text = "Liebe Paktpartner, \nRatatoskr hat festgestellt, dass Origami Tobiichis Stimmung aus unbekannten Gründen gesunken ist und eine Invertierung unvermeidlich scheint. Notfall! Bitte bereitet euch auf die Inspektion vor und passt auf euch auf. \n Hot Games, die ihr Bestes versuchen, dass Origami hübsch aussieht",
        minipack = 0,
    },
    [13310550] = {
