    [1130801] = {
        id = 1130801,
        text = "Königin exklusiv. Kann in einen Basis-ANG Edelsteinslot eingesetzt werden. Kann 1 zusätzliche Engel-Fähigkeit aktivieren",
        minipack = 0,
    },
    [2130502] = {
        id = 2130502,
        text = "Typ 20 Schöpfer - Maschinenschneemann kann regelmäßig Handwerksgegenstände herstellen. Einmal modifiziert, werden bei der Herstellung von Gegenständen zusätzliche Gegenstände gewährt.",
        minipack = 0,
    },
    [266325] = {
        id = 266325,
        text = "Schließe Geister-Prüfungen 3 Mal ab",
        minipack = 0,
    },
    [2130506] = {
        id = 2130506,
        text = "Hinweis: Nicht abgeschossene Stufen verschwinden nach dem Aktualisieren.",
        minipack = 0,
    },
    [1130805] = {
        id = 1130805,
        text = "Königin exklusiv. Kann in einen Basis-ANG Edelsteinslot eingesetzt werden. Kann 2 zusätzliche Engel-Fähigkeiten aktivieren",
        minipack = 0,
    },
    [2130510] = {
        id = 2130510,
        text = "Vorgenommene Modifikationen",
        minipack = 0,
    },
    [266326] = {
        id = 266326,
        text = "Schließe Geister-Prüfungen 6 Mal ab",
        minipack = 0,
    },
    [2130514] = {
        id = 2130514,
        text = "1. Weihnachtsschlacht: \nSchließe die Quests für Geister ab und erhalte Weihnachtsgeschenke von ihnen! Du könntest Schneebälle, 2020 Weihnachts-Sephira, Exklusive 2020 Weihnachten-CG erhalten!\n\n2. Schneemann-Schlacht: \nWeihnachten steht vor der Tür! Lasst uns eine Schneeballschlacht mit Schneemännern machen! Bilde ein Team, um die Schneemann-Herausforderung zu beenden und Materialien zu sammeln, um die Fähigkeiten für die Schneemannfabrik zu verbessern. Und du erhältst Belohnungen wie Schneebälle, Weihnachts-Avatare, Weihnachts-Avatar-Rahmen und Weihnachts-Souvenirs!\n\n3. Weihnachts-Unterstützung: \nWährend des Events erhöhen Pakete, die mit Paketmünzen oder über Aufladen - \"Gut für neue Spieler\", \"Heiß\", \" Zeitlich begrenzt\", \"Kultivierungsfonds\" unter Nachschubstation gekauft werden, den Serverfortschritt. Wenn der Fortschritt zunimmt, werden Rabattbelohnungen angeboten!",
        minipack = 0,
    },
    [2130516] = {
        id = 2130516,
        text = "1. Aktualisiert automatisch 3 Stufen für jeden Spieler täglich um 0:00 Uhr. Tippe auf das Stufen-Symbol, um einen Raum zu erstellen. Einmal abgeschlossen, kannst du die Stufe nicht mehr herausfordern. \n\n2. Du kannst Diamanten ausgeben, um die Stufen sofort zurückzusetzen. Bitte beachte: Nicht herausgeforderte Stufen werden ebenfalls zurückgesetzt. Du hast eine begrenzte Chance, täglich zurückzusetzen. \n\n3. Spieler können sich in der Lobby zusammenschließen, um Eventstufen herauszufordern oder anderen dabei zu helfen (wodurch dieselben Stufenbelohnungen gewährt werden). \n\n4. Du hast täglich begrenzte Unterstützungschancen, die täglich zurückgesetzt werden. Du solltest deine Chancen innerhalb jedes Tages nutzen.",
        minipack = 0,
    },
    [2130518] = {
        id = 2130518,
        text = "Die Schneeschlacht ist vorbei! Deine nicht abgeholten Gegenstände in der Schneemann-Werkstatt sind unten angehängt. Bitte schauen es dir an. \nShop wird nach 10-1-2020 schließen, bitte rechtzeitig tauschen.",
        minipack = 0,
    },
