    [13310535] = {
        id = 13310535,
        text = "Liebe Paktpartner, \n Dank eurer Unterstützung läuft dieses Spiel nun schon seit 1 Jahr. In diesem Jahr haben wir von vielen Spielern Feedback erhalten und an unserer Schwäche gearbeitet. \n Wir werden dieses Spiel weiter verbessern, indem wir bessere Inhalte und ein besseres Spielerlebnis bieten und unsere Community besser machen. \n Vielen Dank für die Unterstützung auf diesem Weg! Wir lieben euch alle!\n Dating hört nie auf!\n Die sich immer weiterentwickelnden Hot Games",
        minipack = 0,
    },
