    [14300216] = {
        id = 14300216,
        text = "Ihr Resümee lautet nur: \"Brauchst du mehr Helfer?\"\nDie Einnahmen steigen, wenn du \"Übungsklasse-Notiz, Feuerwerksmünze, Leuchtmittel, Klebreis-Mehl\" erhältst.",
