    [13310528] = {
        id = 13310528,
        text = "Liebe Paktpartner, \n Danke für eure Unterstützung für Date A Live und Hot Games. Dank eurer Kameradschaft werden die Geister bald ihr erstes Mondneujahrsfest beginnen. \n Danke euch allen für eure beharrliche Unterstützung ! Wir werden uns nach Kräften bemühen, dieses Spiel besser zu machen!\nDating hört nie auf! \n - Hot Games",
        minipack = 0,
    },
    [13310536] = {
        id = 13310536,
        text = "",
        minipack = 0,
    },
    [13310544] = {
        id = 13310544,
        text = "Liebe Paktpartner, \n Dank eurer Unterstützung, feiert Date A Live: Spirit Pledge seinen 1. Bday. Vielen Dank für eure anhaltende Unterstützung. \n Ein Jahr voller intensiver Romantik, dank eurer Unterstützung. \n Ein Jahr voller intensiver Kämpfe, dank eurer Teilnahme. \n Ein Jahr voller großartiger Veranstaltungen, dank eures Vertrauens. \n Wir freuen uns darauf, das Versprechen zu halten und noch mehr süße Erinnerungen mit euch zu erschaffen. \n An diesem 1. Jubiläum versprechen wir, dass wir dieses großartige Spiel weiter verbessern und für noch mehr angenehme Überraschungen sorgen werden. \n DAL: Dating hört nie auf!",
        minipack = 0,
    },
    [13310552] = {
        id = 13310552,
        text = "Ich sagte zu Origami Tobiichi: \"Bitte geh auf ein Date mit mir\". Wie wird sie reagieren...?",
        minipack = 0,
    },
    [13310560] = {
        id = 13310560,
        text = "Warum muss ich die Dienstmädchenkostüme kaufen?!... Ich bin völlig verwirrt!",
        minipack = 0,
    },
    [13310568] = {
