    [190000439] = {
        id = 190000439,
        text = "Die Belohnungen werden freigeschaltet, wenn die Gesamtpunkte aller Mitglieder in deinem Club eine bestimmte Anzahl erreichen. Weitere Details findest du in der Anzeige-Oberfläche der Belohnung! Wenn ein Spieler während des Events von einem Club in einen anderen wechselt, werden die im vorherigen Club verdienten Punkte weiterhin dem vorherigen Club und die im aktuellen Club verdienten Punkte dem aktuellen Club zugerechnet. Die Belohnungen werden nach dem Club abgerechnet, in dem sich ein Spieler gerade befindet.",
        minipack = 0,
    },
    [10503003] = {
        id = 10503003,
        text = "Bombardiert die Feinde an der Front mit dem Flammenstrahl von Camael: Kanone. \nVerursacht Flammen-SCH in Höhe von 1000% ANG. \nCamael: Kanonenform kostet 4 Wut pro Sek. Wenn die Wut auf 0 sinkt, wechselt es wieder in die Hellebardenform.",
