    [3203202] = {
        id = 3203202,
        text = "2. Jede Ebene hat mit 3 Unterebenen. Wenn die Wettbewerbspunkte steigen, kannst du eine Ebene gewinnen, verlieren oder in der aktuellen Ebene bleiben.",
        minipack = 0,
    },
    [3203204] = {
        id = 3203204,
        text = "4. Man erhält eine \"Kampfbewertung\" und wird nach dem Herausfordern von Stufen im Kampfgebieten eingestuft. Man erhält mehr Punkte für einen höheren Rang und verliert Punkte für einen zu niedrigen Rang.",
