    [3203206] = {
        id = 3203206,
        text = "6. In [Leiter] ist der niedrigste Punkt 0 und es gibt keine negativen Punkte. (Wenn deine Kampfbewertung 0 ist, erhältst du keine Punkte, unabhängig von deinem Rang)",
        minipack = 0,
    },
    [3203208] = {
        id = 3203208,
        text = "8. In jedem Zyklus sind aktuelle Sephiroth und von Geistern ausgerüstete Souvenirs an sie gebunden, was bedeutet, dass andere Geister sie nicht benutzen können (sie können jetzt die in der Tasche benutzen)",
        minipack = 0,
    },
    [3203210] = {
        id = 3203210,
        text = "10. Kampfkarten können von Decks erworben werden, die man aus Quest- und Zyklusbelohnungen erhält. Karten können auf ein höheres Level hochgestuft werden.",
        minipack = 0,
    },
    [3203212] = {
        id = 3203212,
        text = "1. Jedes Gebiet hat mehrere Etagen, und jede Etage hat viele Stufen.",
        minipack = 0,
