    [3203214] = {
        id = 3203214,
        text = "3. Jede Etage hat 1 Boss-Stufe. Wenn du den Boss herausforderst, bevor du die regulären Stufen abgeschlossen hast, erhält der Boss zusätzliche Attribute.",
        minipack = 0,
    },
    [3203216] = {
        id = 3203216,
        text = "5. Nur die Boss-Stufe auf der letzten Etage hat Zeitbewertungen und kann wiederholt herausgefordert werden. Andere Stufen haben nur Abschlussbewertungen.",
        minipack = 0,
    },
    [3203218] = {
        id = 3203218,
        text = "7. In jedem Zyklus hat ein Geist 3 Chancen, die Stufen herauszufordern (unabhängig vom Ergebnis). Wenn die Chancen ausgehen, musst du bis zum nächsten Zyklus warten, um sie zu nutzen.",
        minipack = 0,
    },
    [3203220] = {
        id = 3203220,
        text = "1. Die Kampfkarten können in 4 Ebenen unterteilt werden: Gewöhnlich, Fein, Selten und Geschätzt. Sie haben entweder aktive oder passive Effekte",
        minipack = 0,
    },
    [3203222] = {
