        text = "[Inspirationsmaskottchen/Anhaltendes Elend] Fähigkeit-SCH +9%",
        minipack = 0,
    },
    [11312103] = {
        id = 11312103,
        text = "Von Natsumi verwandelte Feinde erhalten eine Schicht Streich. Jede Schicht reduziert 3% VER und ANG. Stapelt bis zu 5 Schichten. Dauert 5 Sek. Bosse, die gegen Verwandeln immun sind, können immer noch von Streich betroffen werden.",
        minipack = 0,
