    [16000405] = {
        id = 16000405,
        text = "5. Each phase unlocks new Story Stages and Challenge Stages, clear previous stage to challenge newly unlocked stages",
        minipack = 0,
    },
    [12033004] = {
        id = 12033004,
        text = "3. In der ersten Phase führt der Spieler die Geister auf eine \"Index\"-Rettungsmission. Schreite in der Haupt-Story voran, um lustige Date-Stufen freizuschalten und die bösen Mächte zu besiegen, die versuchen, Index zu entführen. Wenn du Herausforderungen in einer Szene abschließt, schaltest du Mini-Spiele wie Angeln, Laternenrätsel und Puzzles frei. Schließe sie ab, um jede Menge Eventbelohnungen zu verdienen!",
        minipack = 0,
    },
