    [10921117] = {
        id = 10921117,
        text = "Lässt die gesamte Froststärke ausbrechen, um das vordere Gebiet einzufrieren. Zerbricht dann das Eis, um großen Schaden anzurichten. Die Fähigkeit verursacht Frost-SCH in Höhe von 1600% des ANG des Charakters",
        minipack = 0,
    },
    [10921125] = {
        id = 10921125,
        text = "[Lawine] Hat eine +5% Chance, Frostbiss auszulösen.",
        minipack = 0,
    },
    [10921133] = {
        id = 10921133,
        text = "[Lawine] Fügt Bossen +4% mehr SCH zu.",
        minipack = 0,
    },
    [10921141] = {
        id = 10921141,
        text = "[Lawine] Verursacht 5% mehr SCH an Feinden, die von Frostbiss betroffen sind.",
        minipack = 0,
    },
    [10921149] = {
        id = 10921149,
        text = "[Sturm] Glaubenskosten -1.",
        minipack = 0,
    },
    [10921157] = {
        id = 10921157,
        text = "[Sturm] Bei jedem verursachten SCH besteht eine 12% Chance, 1 Mal zusätzlichen Frost-SCH in Höhe von 50% von Blancs Basis-ANG zu verursachen. Extra-SCH berechnet die VER der Ziele neu.",
        minipack = 0,
    },
    [10921165] = {
        id = 10921165,
        text = "[Sturm] Fähigkeit kostet +5 zusätzlichen Glauben. Der Eiswind bleibt 1 Sek. länger und zieht noch stärker. Die Fähigkeit verursacht Frost-SCH in Höhe von 790% des ANG des Charakters",
        minipack = 0,
    },
    [10921173] = {
        id = 10921173,
        text = "Nach [Frostausbruch] wird alle Stärke entfesselt, um angrenzende Eisstachel zu sprengen und dadurch in einem weiten Gebiet Schaden zu verursachen. Die Fähigkeit verursacht Frost-SCH in Höhe von 750% des ANG des Charakters",
        minipack = 0,
    },
    [10921181] = {
        id = 10921181,
        text = "[Frostausbruch] Nach der Explosion der Eisstachel bleibt für 5 Sek. Eisiger Nebel am Boden. Die Fähigkeit verursacht Frost-SCH in Höhe von 1300% des ANG des Charakters",
        minipack = 0,
    },
    [10921189] = {
        id = 10921189,
        text = "[Frostausbruch] Fähigkeit kostet +5 zusätzlichen Glauben. Beschädigte Ziele verlieren für 5 Sek. 20% VER und 30% Bewegungsgeschwindigkeit. Kann nicht gestapelt werden.",
        minipack = 0,
    },
    [10921197] = {
        id = 10921197,
        text = "[Einfrierender Schlag] schlägt öfter. Das beschworene Eis wird größer. Die Fähigkeit verursacht Frost-SCH in Höhe von 1200% des ANG des Charakters",
        minipack = 0,
    },
    [10921205] = {
        id = 10921205,
        text = "Nach [Einfrierender Schlag] springt Blanc auf, um das Eis zu zertrümmern, wodurch eine blaue Lichtsäule nach oben ausbricht! Die Fähigkeit verursacht Frost-SCH in Höhe von 1900% ihres ANG.",
        minipack = 0,
    },
    [10921213] = {
        id = 10921213,
        text = "[Einfrierender Schlag] Fähigkeit kostet 5 zusätzlichen Glauben. Fähigkeit Krit. Rate +10%, Durchbohren-Rate +10%.",
        minipack = 0,
    },
    [10921221] = {
        id = 10921221,
        text = "Die Verwendung der Fertigkeit lässt jede 1 Sek. Eisstacheln an einer zufälligen Stelle ausbrechen, verursacht Frost-SCH in Höhe von 250% des ANG des Charakters. Greift insgesamt 3 Mal an. Der Effekt kann bis zu 1 Mal jede 6 Sek. ausgelöst werden.",
        minipack = 0,
    },
    [10921229] = {
        id = 10921229,
        text = "Reduziert nach jedem verursachten SCH die Bewegungsgeschwindigkeit der Ziele um 10%. Nach dem Zufügen besteht eine 30% Chance, Reinen SCH in Höhe von 160% ANG zu verursachen. Wird bis zu 1 Mal pro Sekunde ausgelöst. [Hinweis: Reiner SCH berechnet die VER der Ziele nicht]",
        minipack = 0,
    },
