    [14300081] = {
        id = 14300081,
        text = "1. Während des Unterstützungsevents können Spieler durch das Abschließen von Quests, den Kauf von Paketen und das Herausfordern von Hauptinstanzen Unterstützungspunkte sammeln. Event-Quests werden täglich zurückgesetzt. \n\n 2. Alle erworbenen Unterstützungspunkte werden zu den persönlichen Punkten addiert. Nachdem die persönlichen Punkte das Ziel erreicht haben, kannst du das Kunstwerk von \"Purpurroter Alptraum\" ansehen, das Puzzle und große Belohnungen freischalten. \n\n 3. Nach Ende des Events können die besten 100 Spieler Ranglistenbelohnungen erhalten. \n\n 4. Die Ranglistenbelohnungen im Spiel werden nach Ende des Events per Mail versendet.",
        minipack = 0,
    },
