    },
    [14231118] = {
        id = 14231118,
        text = "Geist-Resonanz: \n1. Du kannst Fähigkeitenfragmente verwenden, um die entsprechenden Fähigkeiten im Resonanzsystem zu aktivieren. Ausgerüstete Fähigkeiten fügen allen deinen Geistern einen Buff hinzu, haben aber keinen Effekt auf die Geister anderer im Online-Modus. \n2. Die Aktivierung jeder Fähigkeit",
        minipack = 0,
    },
    [901134] = {
