    [14210163] = {
        id = 14210163,
        text = "Liebe Paktpartner, \nRatatoskr hat festgestellt, dass Origami Tobiichis Stimmung aus unbekannten Gründen gesunken ist und eine Invertierung unvermeidlich scheint. Notfall! Bitte bereitet euch auf die Inspektion vor und passt auf euch auf. \n Hot Games, die ihr Bestes versuchen, dass Origami hübsch aussieht",
        minipack = 0,
    },
    [14210161] = {
        id = 14210161,
        text = "Liebe Paktpartner, \n Dank der neuesten Technologie, die Natsumi zur Verfügung gestellt hat, hat sich Tohkas chattende KI - \"Tohbaka\" - offiziell Ratatoskr angeschlossen. \n Wir haben hart daran gearbeitet, das Spiel zu verbessern und mehr & bessere Inhalte hinzuzufügen. Weitere Geister werden sich später dem Chat anschließen. Bitte freut euch darauf! \n Hot Games",
        minipack = 0,
    },
    [270454] = {
        id = 270454,
        text = "Gespeichert",
        minipack = 0,
    },
    [14210159] = {
        id = 14210159,
        text = "Liebe Paktpartner, \n Heftige Raumbeben in Hot Games haben unseren Entwicklungsserver zum Absturz gebracht, was unsere Arbeit schwer beeinträchtigt und zu einer Verzögerung des Starts geführt hat. Wir entschuldigen uns für die Unannehmlichkeiten und werden Vorkehrungen treffen, um zu verhindern, dass sich so etwas wiederholt. Danke an alle für eure Unterstützung\n Hot Games",
        minipack = 0,
    },
