    },
    [13312009] = {
        id = 13312009,
        text = "A badge with power beyond comprehension, earned in the depth of the deadly Planar World. Collect them to gain personal and Club Support Points (must be in the club for at least 24 hours).",
        minipack = 0,
    },
    [13400201] = {
        id = 13400201,
        text = "Ein süßes Mädchen, das aus einer nahe gelegenen Highschool als Teilzeitkraft erscheint. Obwohl sie unerfahren ist, arbeitet sie hart und lernt schnell.",
        minipack = 0,
    },
    [13400200] = {
        id = 13400200,
        text = "Ein auffälliges Dienstmädchen mit blauen Haaren, sehr beliebt bei den Kunden. Doch irgendwie seufzt sie immer unbewusst.",
        minipack = 0,
    },
    [13400199] = {
        id = 13400199,
        text = "Ein süßes Dienstmädchen, das sich nur selten den Kunden zeigt. Ihre tägliche Magie-Show um 20:00 Uhr ist das Highlight des Cafés.",
        minipack = 0,
    },
    [13400198] = {
        id = 13400198,
        text = "Sie spricht nie mit fremden Kunden, und wenn sie stillsteht, ähnelt sie einer Porzellanpuppe.",
        minipack = 0,
    },
    [13400197] = {
        id = 13400197,
        text = "Sie hat keine Ahnung von ihren Aufgaben, ist aber wegen ihrer Liebenswürdigkeit bei den Kunden immer noch sehr beliebt.",
        minipack = 0,
    },
    [13400196] = {
        id = 13400196,
        text = "Ein Idol-Dienstmädchen, die für ihre Engelsstimme und ihre starke Abneigung gegen männliche Kunden bekannt ist.",
        minipack = 0,
    },
    [13400195] = {
        id = 13400195,
        text = "Ein fleißiges Mädchen, ausgezeichnet darin, alle möglichen Zutaten in einen schrecklichen Auflauf zu verwandeln.",
        minipack = 0,
    },
    [13400194] = {
        id = 13400194,
        text = "Ein sehr sorgfältiges Dienstmädchen, das versucht, alles im Shop an seinem Platz zu halten, aber es ist nur ein Wunsch...",
        minipack = 0,
    },
    [13400193] = {
        id = 13400193,
        text = "Die amtierende Besitzerin des Cafés, die Arbeit für andere Dienstmädchen arrangiert und buchstäblich alles verwaltet. Dennoch kann sie sich manchmal auch niedlich verhalten.",
        minipack = 0,
    },
    [13400192] = {
        id = 13400192,
        text = "Ein Dienstmädchen mit einer mörderischen Aura. Trotz ihrer auffallenden Schönheit sollte man es besser wissen, als sich ihr leichtfertig zu nähern.",
        minipack = 0,
    },
    [13400191] = {
        id = 13400191,
        text = "Ein Dienstmädchen, bekannt als der \"Date-Guru\". Ihre kontaktfreudigen Persönlichkeiten verwirren andere oft.",
        minipack = 0,
    },
    [13400190] = {
        id = 13400190,
        text = "Das beliebteste Dienstmädchen im Café. Diese Unruhestifterin wird von den Kunden immer verziehen, weil sie viel zu süß ist.",
        minipack = 0,
    },
    [13400189] = {
        id = 13400189,
        text = "Ein blondes Dienstmädchen, das aggressiv aussieht, aber dennoch perplex werden kann, wenn es von Kunden beschimpft wird.",
        minipack = 0,
    },
    [13400188] = {
        id = 13400188,
        text = "Ein süßes Dienstmädchen mit Brille, das andere immer verspottet, aber wenn du es wagst, sie zu provozieren, würde sie dir von hinten Streiche spielen.",
        minipack = 0,
    },
    [13400187] = {
        id = 13400187,
        text = "Ein unschuldig aussehendes Dienstmädchen mit kurzen Haaren. Kümmere dich nicht um ihre gelegentlichen scharfen Bemerkungen.",
        minipack = 0,
    },
    [13400186] = {
        id = 13400186,
        text = "Ein aufgeschlossenes Dienstmädchen mit Pferdeschwanz, das gut massieren kann, ihre Offenheit bringt die Kunden manchmal in Verlegenheit.",
        minipack = 0,
    },
    [13400185] = {
        id = 13400185,
        text = "Ein reifes Dienstmädchen mit Müdigkeit im Gesicht. Obwohl sie geistesabwesend ist, macht sie das mit ihrer höflichen Haltung und ihren Manieren wieder wett.",
        minipack = 0,
    },
    [13400184] = {
        id = 13400184,
        text = "Ein Dienstmädchen, das sich um Kunden kümmert wie ein Nachbarmädchen um seinen Bruder.",
        minipack = 0,
    },
    [13400183] = {
        id = 13400183,
        text = "Ein normal aussehendes Dienstmädchen, das keinen Widerstand gegen gut aussehende reife Männer hat. Die Art, wie sie spricht, lässt vermuten, dass sie kenntnisreich ist.",
        minipack = 0,
    },
    [13400182] = {
        id = 13400182,
        text = "Ein Dienstmädchen mit rundem Gesicht und Zopf. Sie verehrt das Dienstmädchen \"Dating-Meister\" und ist immer bei ihr.",
        minipack = 0,
    },
    [13400181] = {
        id = 13400181,
        text = "Ein tüchtiges Dienstmädchen mit Pferdeschwanz. Sie ist immer enthusiastisch gegenüber hübschen jungen Gästen und macht sich Sorgen um ihre zukünftige Ehe.",
        minipack = 0,
    },
