    [13316840] = {
        id = 13316840,
        text = "3. [Research]\nSelect 4 different kinds of materials for the research. If the combination is correct, a corresponding recipe will be unlocked.\nUnlocking recipes is the main way to get Revenue, so unlock as many recipes as possible.\nIf the research fails or gives a repeated recipe, you will get Recipe Insight instead.\nRecipe Insight can be used to level up recipes or exchanged for random recipes at the Store.",
        minipack = 0,
    },
    [13316839] = {
        id = 13316839,
        text = "2. [Adventure]\nCats can be dispatched to complete Exploration Quests for Recipe Materials.\nStory Quests are the main way to get Maids, and some of them require cats with a \"specified personality\".\nOnce dispatched, the cats will no longer \"Keep Shop\" or gain EXP bonus from toys. The cats cannot go back to the shop until quest rewards are claimed.",
        minipack = 0,
    },
    [13316838] = {
        id = 13316838,
        text = "1. [Cattery]\nYou can view the stats of your cats here.\nIn the Cattery, you can tap \"Recruit\" to recruit cats.\nYou get 3 Recruit Tickets at midnight every day, and you can have up to 12 tickets. When the card pool is empty, recruitment cannot be continued.\nCat stats mainly include Charisma and Discipline. Charisma can be converted into Shop Revenue, and Discipline can be used to reduce Exploration duration.\nCats can be leveled up by \"feeding snacks\" and \"placing toys\". After the level up, cats will gain Charisma and Discipline according to their talents.",
        minipack = 0,
    },
