    [2101085] = {
        id = 2101085,
        text = "Geschrieben an der Ecke des Tagebuchs: Ich werde meiner Frau das Handy geben, das ich bei der jährlichen Firmenfeier gewonnen habe, und sie gibt mir etwas Geld. Ka-tsching!",
        minipack = 0,
    },
    [2101087] = {
