    },
    [2101091] = {
        id = 2101091,
        text = "Worte des Programmierers: Es ist unmöglich, alle Fehler zu beheben, nicht bevor ich tot bin.",
        minipack = 0,
    },
    [2101093] = {
        id = 2101093,
        text = "Notiz des Programmierers: Sie können einfach nicht aufhören, kurz vor Feierabend neue Anforderungen zu schicken. Können sie mich nicht für nur 1 Nacht gut schlafen lassen?",
        minipack = 0,
    },
    [2101095] = {
        id = 2101095,
        text = "Der praktische Mikro-Feuertopf für die Nachtschicht schmeckt sauer und bitter. Und daneben steht eine Kiste mit Flussschnecken-Reisnudeln...",
        minipack = 0,
    },
    [2101097] = {
