        text = "Das Schließfach ist mit Tüchern gefüllt. Hat der Besitzer sie auf einem Großmarkt gekauft?",
        minipack = 0,
    },
    [2101099] = {
        id = 2101099,
        text = "In den Schließfächern hängen viele schlichte Hemden, die Programmierer mögen. Rot, grün und blau... alles Mögliche.",
        minipack = 0,
    },
    [2101101] = {
