        text = "Es ist gefüllt mit einem funktionellen Getränk für die Nachtschicht - [Hot Games Cola].",
        minipack = 0,
    },
    [2101103] = {
        id = 2101103,
        text = "Geheimnis der Arbeit: Arbeit macht glücklich. Arbeite weiter und du wirst immer glücklich sein. Die Zusammenarbeit mit anderen macht dich noch glücklicher.",
        minipack = 0,
    },
    [2101105] = {
        id = 2101105,
        text = "Eine Ecke des niedlichen Welpenkissens ist nass. Ich wette, sein Besitzer sabbert, wenn er schläft...",
        minipack = 0,
    },
    [2101107] = {
