    [13313467] = {
        id = 13313467,
        text = "Find the lair of the Mesopotamian Air Pirates and join the operation to annihilate them!",
        minipack = 0,
    },
    [63578] = {
        id = 63578,
        text = "Reise durch Zeit und Raum, nur um dich wieder zu treffen - \nDieser Raum, der als [Raum der Erinnerungen] bezeichnet wird, besteht aus den Erinnerungen von Origami. Der Zeitstrahl dieses Raumes ist ziemlich instabil. Du musst diesen Raum erkunden, verschiedene Quests abschließen und [Gedenk-Dates] freischalten, dann findest du Origami im Date. \nDu kannst nicht mittendrin aufhören, wenn du ein Gedenk-Date beginnst. Das Abschließen oder Verlassen eines Dates führt zu einer Erinnerungsunterbrechung und macht es unmöglich, das Date erneut zu betreten. Bitte triff deine Wahl des Dates mit Vorsicht. \nJedes [Gedenk-Date] hat 1 verstecktes Erinnerungsfragment. Sammle alle Erinnerungsfragmente, um das letzte Date freizuschalten. \n\nZeitstrahl-Sprung: \nRatatoskr hat ein spezielles Gerät entwickelt, um Energie im Raum der Erinnerungen zu sammeln. \n\nDu kannst etwas Energie verbrauchen, um zu einem anderen Zeitstrahl zu springen und ein anderes Erinnerungsstück zu erforschen. \nJedes Mal, wenn du zu einem anderen Zeitstrahl springst, gibt es ein neues [Gedenk-Date], und du kannst nicht zu einem früheren Gedenk-Date zurückkehren. Achte also darauf, dass du das Date abschließt, bevor du den Sprung machst.",
        minipack = 0,
    },
