    },
    [32317] = {
        id = 32317,
        text = "",
        minipack = 0,
    },
    [13310533] = {
        id = 13310533,
        text = "Liebe Paktpartner, \n Nach monatelangem Training ist Shekhinah Tohka jetzt viel mächtiger. Auch der \"Durchbohren\"-Effekt wurde verbessert. \n Wir haben unsere Versprechen erfüllt. Seid versichert, das das Spiel besser und eure Waifu stärker wird (mit einem größeren Appetit). \n Ein Designer unter dem Pseudonym D·A·L",
        minipack = 0,
    },
    [13310532] = {
        id = 13310532,
        text = "Liebe Paktpartner, \n Im letzten Update haben wir den Effekt von \"Durchbohren\" geändert und Tohka entsprechend der Nachfragen verstärkt. \n Bitte glaubt uns, dass wir am Ende unsere Versprechen erfüllen werden. Wir haben hart daran gearbeitet, dieses Spiel zu verbessern und der Marke zu helfen. Lasst uns wie immer unsere Mängel erkennen und helft uns, uns zu verbessern. \n - Die vertrauenswürdigen Hot Games",
        minipack = 0,
    },
    [1706042] = {
        id = 1706042,
        text = "Programm wird imitiert - bee bo bee bo～～",
        minipack = 0,
    },
    [13310529] = {
        id = 13310529,
        text = "Liebe Paktpartner, \n Dank eurer Kameradschaft werden die Geister bald ihr erstes Mondneujahrsfest beginnen. \n Danke euch allen, dass ihr uns geholfen habt, zu wachsen und besser zu werden! Wir wissen eure Unterstützung und Toleranz wirklich zu schätzen!\n Dating hört nie auf! Wir lieben euch alle!\n - Designer Sima",
        minipack = 0,
    },
    [42106] = {
