    [13100052] = {
        id = 13100052,
        text = "Es ist möglich, in Phase 2 das Nian-Biest zu beschwören. Beachte, dass du den Beschwörungsgegenstand nach Beginn des Events benutzen musst, sonst wird der Gegenstand verschwendet. Nachdem der Event begonnen hat, kannst du mit Feuerwerkskörpern das Nian-Biest in der Stadt beschwören. Finde es, bevor die Zeit abläuft. Es kann jeweils nur ein Nian-Biest in der Stadt sein. Nachdem ein Nian-Biest gefangen wurde oder abgelaufen ist, kannst du mit Feuerwerkskörpern ein neues beschwören.",
        minipack = 0,
    },
    [13100051] = {
        id = 13100051,
        text = "Die Neujahrs-Quest umfasst: Roter Umschlag Quest, Date-Quest, zufällige Quest und Minispiel. Die Geister brauchen an diesem Feiertag deine Hilfe. Du kannst die Lieblings-Mädchen Quest alle 3 Stunden kostenlos oder mit Diamanten wechseln. Schließe Quests ab, um Punkte zu verdienen, mit denen du im Tausch Belohnungen eintauschen kannst!\nRoter Umschlag Quest: Hol einfach den roten Umschlag ab. \nDate-Quest: Jeder Geist hat limitierte Date-Quests, und Spieler können diese abschließen, um Belohnungen zu erhalten. Abgeschlossene Date-Quests erscheinen nicht mehr. Wenn ein Geist keine neuen Date-Quests hat, wechsel zu einem anderen Geist, um neue Date-Quests zu erhalten. \nZufällige Quest: Befolge die Tipps, um die Quests abzuschließen. \nMinispiel-Quest: Befolge die Tipps zum Abschließen von Minispielen.\nP.S: Bitte vergiss nicht, die Belohnungen abzuholen! Nicht abgeholte Belohnungen werden dir in dein Postfach geschickt.",
        minipack = 0,
    },
