    [2108001] = {
        id = 2108001,
        text = "Prüfung: Mobius",
        minipack = 0,
    },
    [2108003] = {
        id = 2108003,
        text = "Prüfung: Illusion",
        minipack = 0,
    },
    [2108005] = {
        id = 2108005,
        text = "Alles verändert sich, und alle Regeln sind verzerrt. Eine mutierte Flut kommt nach der anderen, der Thron bebt. Aber das Schwert in den Händen des Königs bleibt vollkommen ruhig.",
        minipack = 0,
    },
    [2108007] = {
        id = 2108007,
        text = "1. Sim-Prüfung ist ein zeitlich begrenzter Event, bei dem du Geister ausprobieren kannst. Verpass es nicht!",
        minipack = 0,
    },
    [2108009] = {
        id = 2108009,
        text = "3. In dieser Sim-Prüfung steuerst du Origami. Viel Spaß.",
        minipack = 0,
    },
    [2108011] = {
        id = 2108011,
        text = "Willst du den Sim-Modus dieses Geistes betreten?",
        minipack = 0,
    },
    [2108013] = {
        id = 2108013,
        text = "Sim-Prüfung: Territorium",
        minipack = 0,
    },
    [2108015] = {
        id = 2108015,
        text = "Im Guerillakrieg musst du in kleinen Kämpfen in der feindlichen Verteidigungslinie Ärger machen und die Feinde infiltrieren. Versuche, den Vorteil des Solokampfes zu maximieren.",
        minipack = 0,
    },
    [2108017] = {
        id = 2108017,
        text = "Bei einer Attacke musst du ein bestimmtes Ziel ausschalten. Sei schnell und präzise. Erledige es so schnell wie möglich.",
        minipack = 0,
    },
    [2108019] = {
        id = 2108019,
        text = "Extra-Story: Konflikt",
        minipack = 0,
    },
    [2108021] = {
        id = 2108021,
        text = "Es ist zufällig und doch vermeidbar. Irgendetwas stimmt nicht mit Tohkas Astral-Kleid. Was erwartet uns als Nächstes?",
        minipack = 0,
    },
    [2108023] = {
        id = 2108023,
        text = "Konfrontiere das Herz, kämpfe mit dem Schwert. Es ist schwer und beängstigend, sich seiner Vergangenheit zu stellen. Aber deshalb werden diejenigen, die über ihren Weg nachdenken, stärker werden.",
        minipack = 0,
    },
    [2108025] = {
        id = 2108025,
        text = "Verschwörung",
        minipack = 0,
    },
    [2108027] = {
        id = 2108027,
        text = "Als unerwartete Feinde weiter vorrücken, schließt sich Mayuri dem Kampf an. Da Mayuri neu in dieser Welt ist, wie wird sie diese Seite der Menschheit sehen?",
        minipack = 0,
    },
    [2108029] = {
        id = 2108029,
        text = "Feinde im Dunkeln zeigen sich einer nach dem anderen. Die goldenen Flügel breiten sich rechtschaffend aus! Falle vs. Mut, welche Seite wird gewinnen?",
        minipack = 0,
    },
    [2108031] = {
        id = 2108031,
        text = "[Begegnen]",
        minipack = 0,
    },
    [2108033] = {
        id = 2108033,
        text = "Es scheint, dass der neu erschienene Geist sehr an dieser Welt interessiert ist. Aber einigen gefällt nicht, wie sie sich gezeigt hat.",
        minipack = 0,
    },
    [2108035] = {
        id = 2108035,
        text = "Natsumi fühlt Origamis Hass und beschließt, ernsthaft zu kämpfen.",
        minipack = 0,
    },
    [2108037] = {
        id = 2108037,
        text = "Extra-Story - Verwandeln",
        minipack = 0,
    },
    [2108039] = {
        id = 2108039,
        text = "Die Kraft der Verjüngung schwillt in dem winzigen Körper weiter an. Weiterkämpfen oder... lieber fliehen?",
        minipack = 0,
    },
    [42157] = {
        id = 42157,
        text = "SSS-Klasse Energie-Edelstein, erhalte es, um einen SSS-Klasse Edelstein für eine zufällige Fähigkeit von [Natsumi] zu erhalten. (Wird nach Erhalt automatisch verwendet)",
