    [2109021] = {
        id = 2109021,
        text = "1. Halloween-Horror Event ist online! Fröhliches Halloween Leute!",
        minipack = 0,
    },
    [2109023] = {
        id = 2109023,
        text = "3. Der Halloween-Event besteht aus 4 Teilen. Die ersten 3 Stufen erzählen die Erzählung von Yoshino, die sich im Wald verirrt hat. Die letzte ist eine Rennstufe, die so schnell wie möglich abgeschlossen werden muss, um eine bessere Belohnung zu erhalten. (Die Belohnung für jede Quest kann während des Events einmal abgeholt werden)!",
        minipack = 0,
    },
    [2109025] = {
        id = 2109025,
        text = "1. Die Spieler werden nach der Zeit eingestuft, mit der die letzte Stufe [Verrückte Party] auf der Rennrangliste beendet wurde. \n2. Die Belohnungen werden auf der Grundlage der rechts aufgeführten Regeln per Mail verschickt. \n3. Das vorgeschlagene Level für den Modus liegt bei etwa Lv.50. Achte darauf, geeignete Sephiroth und Geister auszuwählen. \n4. Diejenigen, die mit der gleichen Zeit ins Ziel kommen, werden danach gereiht, wer es am frühesten abgeschlossen hat. \n5. Wenn der Event endet, können Spieler in Stufen die aktuelle Stufe noch für Stufenbelohnungen abschließen, aber der Event hat keinen Einfluss auf die Rangliste mehr. Bitte beachten!",
        minipack = 0,
    },
