    [10203002] = {
        id = 10203002,
        text = "Stürmt vorwärts und schlägt schnell 3 Mal zu, bevor die Laserkanone abgefeuert wird, um die vorderen Feinde eine Zeit lang zu bombardieren. \nHieb: Verursacht 3 Mal Physischen SCH in Höhe von 120% ANG. \nBombardieren: Verursacht 6 Mal Blitz-SCH in Höhe von 100% ANG.",
