    [63016] = {
        id = 63016,
        text = "Neben Spielbenachrichtigungen werden einige Eventbelohnungen und Entschädigungsgegenstände als Anhang per Mail verschickt. \nBitte beachte, dass Mails nur 7 Tage oder weniger aufbewahrt werden, wenn du bereits 200 Mails hast. Sie werden der Reihe nach gelöscht, wenn der Speicher voll ist. Überprüfe sie oft, damit du nichts verpasst. \nGelesene Mails mit abgeholtem Anhang werden automatisch gelöscht. \nMails können bis zu 200 rote Umschläge für 7 Tage speichern. Wenn das Limit erreicht ist, werden sie der Reihe nach gelöscht. Hole also rechtzeitig deine Belohnungen ab.",
        minipack = 0,
    },
