    [405149] = {
        id = 405149,
        text = "Probe-Sephira für Geister des Events [Evil Triumph] Unter-Sephira, erzeugt durch das Invertieren von Sephira-Kristall, enthält große dunkle Energie. Sephira ist Geburah. Enthält 4 zufällige Attribute",
