    [2130521] = {
        id = 2130521,
        text = "Event-Intro",
        minipack = 0,
    },
    [2130520] = {
        id = 2130520,
        text = "1. Pracht des Feuerwerks: \nNimm am Neujahrsevent teil und sammle Materialien zur Herstellung von Feuerwerk -- Schießpulver, Rotes Papier und Leuchtmittel! \n\nBuntes Feuerwerk ist unverzichtbar, um eine bunte Welt des Segens zu erschaffen -- Liebes-Feuerwerk, Reichtums-Feuerwerk, Gesundheits-Feuerwerk, Glücksfeuerwerk, jeder mit seinem eigenen leidenschaftlichen Segen. \n\nJede Art von Feuerwerk kostet unterschiedliche Materialien. Sammle so viele, wie du kannst! \n\nErleuchte Tengu-Stadt mit einem wunderschönen Feuerwerk! Lass die ganze Welt deine Wünsche sehen!",
        minipack = 0,
    },
    [405150] = {
        id = 405150,
        text = "Probe-Sephira für Geister des Events [Evil Triumph] Unter-Sephira, erzeugt durch das Invertieren von Sephira-Kristall, enthält große dunkle Energie. Sephira ist Tiphareth. Enthält 4 zufällige Attribute",
