    },
    [10941191] = {
        id = 10941191,
        text = "[Eisensand-Schwert] Wenn der Wirbelwind kurz davor ist, sich aufzulösen, verwendet er seine letzte Kraft, um zu explodieren und Eisensand zu erzeugen, der Gegner erfasst. Die Fähigkeit verursacht Blitz-SCH in Höhe von insgesamt 1400% des ANG des Charakters.",
        minipack = 0,
    },
    [10941199] = {
        id = 10941199,
        text = "[Echter Donner] Fügt 4 kleinere Donnerschläge hinzu. Die Fähigkeit verursacht Blitz-SCH in Höhe von insgesamt 930% des ANG des Charakters.",
        minipack = 0,
    },
    [10941207] = {
        id = 10941207,
        text = "[Echter Donner] Erzeugt einen Donnerball im Zentrum des Donners, der sich immer weiter ausdehnt, indem er die Energie der Blitze in der Nähe absorbiert, bis er explodiert. Die Fähigkeit verursacht Blitz-SCH in Höhe von insgesamt 1300% des ANG des Charakters.",
